import React, { useState, useEffect, useRef, useMemo } from "react";

/* ============================================================
   EL ANALISTA  ·  v5
   De los 20 a los 50, un año por turno.
   Dieciocho minijuegos, un temario de finanzas en cinco niveles que
   sube contigo, una cartera que reparte activo por activo y un
   informe de cierre que te explica qué acabas de aprender.
   ============================================================ */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Rubik:wght@400..900&family=Nunito:wght@400..800&display=swap');

.ea-root{
  /* Las tres voces del juego, en un solo sitio. Antes eran Archivo Narrow
     en mayusculas espaciadas mas IBM Plex Mono para las cifras: la
     combinacion que hoy se lee como «esto lo hizo una IA». Ahora es voz de
     videojuego: Rubik, redondeada y gorda, para titulos y cifras, y Nunito
     para el texto corrido. Las cifras de Rubik son proporcionales de
     serie («1111» mide tres cuartos de «0000»), pero trae las de ancho
     fijo: tabular-nums va en todo el juego, no solo en .ea-mono, para que
     ningun numero que sube —el rodillo del patrimonio, los contadores—
     baile al cambiar de digito. Cambiar de fuente es cambiar estas tres
     lineas. */
  --f-dis:'Rubik','Arial Rounded MT Bold',system-ui,sans-serif;
  --f-txt:'Nunito',system-ui,-apple-system,"Segoe UI",sans-serif;
  --f-num:'Rubik',system-ui,sans-serif;
  --tinta:#06170D; --fieltro:#0B3A1F; --borde:#1F6B3E;
  --papel:#F7F7F5; --papel2:#E9EEF5; --tintaPapel:#3D3D3D;
  --cobre:#B9532A; --verde:#4FA05C; --rojo:#B23B27; --gris:#6B6B6B;
  --hueso:#EDEDE8; --tenue:#9FB8A8;
  background:var(--papel); color:var(--tintaPapel); min-height:100vh;
  font-family:var(--f-txt); font-variant-numeric:tabular-nums;
  font-size:15px; line-height:1.55; padding:16px;
}
.ea-root *{box-sizing:border-box}
.ea-root{overflow-x:clip}
.ea-dis{font-family:var(--f-dis); text-transform:uppercase; letter-spacing:.04em; font-weight:700}
.ea-mono{font-family:var(--f-num); font-variant-numeric:tabular-nums; font-weight:600}

/* Los titulares grandes se escriben como se habla, no en MAYUSCULAS
   ESPACIADAS: esa era la otra mitad del look de IA. Las mayusculas se
   quedan en las etiquetas pequeñas —«TU PATRIMONIO», «CIERRE DEL AÑO»—,
   que es donde sirven para ordenar. */
.ea-h1,.ea-memoTit,.ea-final,.ea-nombre,.ea-claseT,.ea-jnombre,.ea-opcionN,
.ea-anuncioJN,.ea-anuncioEscT,.ea-nuevoT,.ea-vidaN,.ea-titularV,.ea-finTit,
.ea-itemN,.ea-perfilT,.ea-lecT,.ea-guiaT,.ea-notiT,.ea-glosT,.ea-cifraV,.ea-fondoN,.ea-wname{
  text-transform:none; letter-spacing:-.015em; font-weight:800}
.ea-h1{letter-spacing:-.035em}
/* la etiqueta pequeña que va dentro de .ea-jnombre sigue siendo etiqueta */
.ea-jnombre span{text-transform:uppercase;letter-spacing:.2em;font-weight:700}
/* los botones: con caracter, sin gritar */
.ea-btn,.ea-btnO,.ea-comprar,.ea-aplicar,.ea-jugarYa,.ea-mini,.ea-tab,.ea-grupo{letter-spacing:.06em}

/* Rubik es mas ancha que Archivo Narrow, que era estrecha a proposito.
   La linea de la firma en versales espaciadas —«MERIDIANO ESTUDIOS
   ECONOMICOS · VENEZUELA»— dejo de caber junto al dinero y lo empujaba
   debajo, desalineado. En minusculas ocupa la mitad y se lee mejor. */
.ea-sub.ea-quien{text-transform:none;letter-spacing:.005em;font-weight:600;font-size:12.5px}
/* y si aun asi no cabe —nombre largo, pantalla estrecha—, el dinero baja
   pero pegado a la derecha, no suelto a media placa */
.ea-reloj{margin-left:auto}

.ea-wrap{max-width:1100px;margin:0 auto}
.ea-placa{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-end;justify-content:space-between;
  border:1px solid var(--borde);background:var(--fieltro);padding:15px 20px;border-radius:3px 3px 0 0}
.ea-nombre{font-size:25px;line-height:1;color:var(--papel)}
.ea-sub{font-size:11.5px;color:var(--tenue);letter-spacing:.14em;margin-top:5px}
.ea-reloj{text-align:right;font-size:11.5px;color:var(--tenue);letter-spacing:.1em}
.ea-plata{font-size:23px;color:var(--papel)}
.ea-plata.neg{color:var(--rojo)}

.ea-cinta{border:1px solid var(--borde);border-top:none;background:#04220F;padding:8px 20px;
  font-size:12px;color:var(--tenue);display:flex;gap:10px;align-items:baseline;border-radius:0 0 3px 3px}
.ea-cintaK{color:var(--cobre);flex-shrink:0;font-size:11px;letter-spacing:.14em}

.ea-grid{display:grid;grid-template-columns:300px 1fr;gap:18px;margin-top:18px;align-items:start}
@media(max-width:880px){.ea-grid{grid-template-columns:1fr}}

.ea-panel{border:1px solid var(--borde);background:var(--papel);padding:16px 18px;border-radius:3px}
.ea-rot{font-size:11px;letter-spacing:.2em;color:var(--gris);margin-bottom:12px}

.ea-tabs{display:flex;flex-wrap:wrap;gap:0;border:1px solid var(--borde);border-bottom:none;background:var(--papel)}
.ea-tab{flex:1;min-width:70px;background:transparent;border:none;border-bottom:2px solid transparent;color:var(--gris);
  padding:9px 4px;font:inherit;font-size:11px;letter-spacing:.12em;cursor:pointer;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-tab.on{color:var(--tintaPapel);border-bottom-color:var(--cobre)}
.ea-tab:hover{color:#262626}

.ea-stat{margin-bottom:10px}
.ea-statTop{display:flex;justify-content:space-between;font-size:12px;letter-spacing:.08em;margin-bottom:4px}
.ea-bar{height:5px;background:#041F0E;position:relative;overflow:hidden}
.ea-fill{height:100%;background:var(--cobre);transition:width .5s ease}
.ea-fill.ene{background:var(--verde)}
.ea-fill.baja{background:var(--rojo)}

.ea-fila{display:flex;justify-content:space-between;gap:8px;font-size:13px;padding:5px 0;border-bottom:1px dotted var(--borde)}
.ea-fila:last-child{border-bottom:none}

.ea-slider{width:100%;-webkit-appearance:none;appearance:none;height:3px;background:#041F0E;outline:none;margin:7px 0 2px}
.ea-slider::-webkit-slider-thumb{-webkit-appearance:none;width:13px;height:13px;background:var(--cobre);cursor:pointer;border-radius:0}
.ea-slider::-moz-range-thumb{width:13px;height:13px;background:var(--cobre);cursor:pointer;border:none;border-radius:0}

/* Comprar es la accion que mueve dinero: no puede tener el mismo peso
   visual que un boton cualquiera. */
.ea-comprar{background:var(--cobre);color:#20120A;border:1px solid var(--cobre);padding:9px 18px;
  font:inherit;font-size:12.5px;letter-spacing:.12em;cursor:pointer;margin-top:8px;border-radius:2px;
  transition:background .15s,border-color .15s,transform .12s;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-comprar:hover:not(:disabled){background:#C86A3E;border-color:#C86A3E}
.ea-comprar:active:not(:disabled){transform:translateY(1px)}

.ea-item{border-bottom:1px dotted var(--borde);padding:11px 0}
/* Lo que ya es tuyo se apaga, para que la vista encuentre sola lo que
   todavia no tienes. Sin opacity en el contenedor: asi la etiqueta de
   «ya lo tienes» sigue legible en verde. */
.ea-item.tuyo{background:rgba(61,61,61,.05);padding-left:9px;padding-right:9px;border-radius:2px;
  border-left:2px solid rgba(79,160,92,.45)}
.ea-item.tuyo .ea-itemN{color:rgba(61,61,61,.62)}
.ea-item.tuyo .ea-itemD{color:rgba(61,61,61,.5)}
.ea-item.tuyo .ea-etq{opacity:.45}
.ea-item.tuyo .ea-mono{color:rgba(61,61,61,.55)}
.ea-item:last-child{border-bottom:none}
.ea-itemTop{display:flex;justify-content:space-between;gap:10px;align-items:baseline}
.ea-itemN{font-size:13.5px;color:var(--tintaPapel);font-family:var(--f-dis);
  text-transform:uppercase;letter-spacing:.05em;font-weight:700}
.ea-itemD{font-size:12px;color:var(--gris);margin-top:4px}
.ea-mini{background:transparent;border:1px solid var(--borde);color:var(--tintaPapel);font:inherit;font-size:11px;
  letter-spacing:.1em;padding:5px 10px;cursor:pointer;margin-top:8px;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-mini:hover:not(:disabled){border-color:var(--cobre);color:#262626}
.ea-mini:disabled{opacity:.35;cursor:not-allowed}
.ea-tengo{color:var(--verde);font-size:11px;letter-spacing:.12em;margin-top:8px;display:inline-block}

.ea-memo{background:var(--papel);color:var(--tintaPapel);padding:26px 26px 22px;position:relative;
  border-radius:4px;
  box-shadow:0 18px 40px rgba(0,51,24,.28), 0 2px 0 var(--papel2);
  animation:ea-in .4s cubic-bezier(.2,.7,.3,1)}
@keyframes ea-in{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.ea-memoHead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;
  border-bottom:2px solid var(--tintaPapel);padding-bottom:8px;margin-bottom:15px;font-size:11px;letter-spacing:.18em}
.ea-memoHead.clave{border-bottom:4px double var(--tintaPapel)}
.ea-memoTit{font-size:26px;line-height:1.08;margin:0 0 10px;color:#262626}
.ea-memoTxt{font-size:15.5px;margin:0;color:#3D3D3D}
/* la linea que dice de que decision viene una consecuencia */
.ea-porQue{display:inline-flex;align-items:center;gap:6px;margin:0 0 8px;padding:4px 10px 4px 8px;
  border-radius:999px;background:#EFE7F8;color:#5B3690;font-size:12.5px;font-weight:700;line-height:1.3}
.ea-porQue svg{flex-shrink:0}
.ea-memoDrama .ea-porQue{display:flex;width:fit-content;margin:0 auto 10px}

/* ---- tu camino, al final de la partida ---- */
.ea-camino{margin-top:24px;text-align:left}
.ea-arbol{margin-top:20px}
.ea-arbolT{display:flex;align-items:center;gap:7px;font-size:12px;letter-spacing:.16em;font-weight:800;margin-bottom:10px}
.ea-nodo{border-left:3px solid;padding:2px 0 2px 14px;margin-left:7px;animation:ea-camIn .5s ease-out backwards}
.ea-nodoHijo{margin-top:12px}
.ea-nodoT{font-size:15.5px;font-weight:800;color:#262626;margin:0 0 7px;line-height:1.25;text-transform:none;letter-spacing:-.01em}
.ea-nodoT .ea-mono{font-size:11.5px;color:var(--gris);font-weight:600;margin-right:8px;letter-spacing:.04em}
.ea-rumbos{display:flex;flex-direction:column;gap:6px}
.ea-rumboSi{display:flex;align-items:center;gap:7px;border:2px solid;border-radius:12px;padding:8px 11px;
  font-weight:700;font-size:13.5px;background:#FFFFFF;box-shadow:0 2px 0 rgba(0,0,0,.06)}
.ea-rumboSi svg{flex-shrink:0}
.ea-rumboSi em{margin-left:auto;font-style:normal;font-size:11px;font-weight:700;letter-spacing:.06em;
  text-transform:uppercase;opacity:.75;white-space:nowrap}
.ea-rumboNo{border:1.5px dashed #CFCFC8;border-radius:12px;padding:7px 11px;font-size:13px;color:#9A9A94}
.ea-rumboNo small{display:block;margin-top:2px;font-size:11.5px;color:#7A4FB0;font-weight:700}
.ea-hijos{margin-top:4px}
.ea-descubre{margin-top:22px;padding-top:14px;border-top:1px solid #E2E2DC}
.ea-descubreN{font-size:13.5px;color:#3D3D3D}
.ea-descubreN .ea-mono{font-size:20px;font-weight:800;color:#7A4FB0;margin-right:4px}
.ea-descubreB{height:8px;border-radius:99px;background:#EFE7F8;margin-top:8px;overflow:hidden}
.ea-descubreB div{height:100%;border-radius:99px;background:#7A4FB0;animation:ea-camBarra 1.2s .3s ease-out backwards}
@keyframes ea-camIn{from{opacity:0;transform:translateX(-10px)}}
/* ---- escenarios con probabilidad ---- */
.ea-opAzar{display:inline-flex;align-items:center;gap:4px;margin-left:8px;font-size:10.5px;letter-spacing:.08em;
  color:#2D6FA3;background:#E6F0F8;border-radius:99px;padding:2px 8px;vertical-align:middle}
.ea-azar{margin:16px 0 4px;text-align:left}
.ea-azarK{font-size:11.5px;letter-spacing:.14em;color:var(--gris);margin-bottom:7px}
.ea-azarB{position:relative;display:flex;height:16px;border-radius:99px;overflow:visible;background:#E8E8E2}
.ea-azarT{height:100%;opacity:.35;transition:opacity .3s}
.ea-azarT:first-child{border-radius:99px 0 0 99px}
.ea-azarT:last-child{border-radius:0 99px 99px 0}
.ea-azarT.exito{background:#4FA05C}
.ea-azarT.parcial{background:#C9A227}
.ea-azarT.fallo{background:#B23B27}
.ea-azarT.sale{opacity:1;animation:ea-azarSale .5s 1.1s ease-out backwards}
.ea-azarA{position:absolute;top:-7px;left:var(--a);width:0;height:0;margin-left:-7px;border:7px solid transparent;
  border-top:9px solid #262626;animation:ea-azarAguja 1.2s cubic-bezier(.3,1.4,.5,1) backwards}
.ea-azarL{display:flex;flex-wrap:wrap;gap:4px 12px;margin-top:8px;font-size:12px;color:#9A9A94}
.ea-azarL span.sale{color:#262626;font-weight:800}
.ea-azarL b{font-weight:700}
@keyframes ea-azarAguja{0%{left:0}60%{left:100%}100%{left:var(--a)}}
@keyframes ea-azarSale{from{opacity:.35}}
.ea-finalH{margin:18px auto 4px;max-width:520px;padding:16px 18px;border-radius:16px;background:#1A1530;color:#F4EFFF;
  text-align:center;box-shadow:0 10px 30px rgba(42,22,80,.25);animation:ea-finalIn .7s cubic-bezier(.2,.9,.3,1.2) .2s backwards}
.ea-finalHK{display:flex;align-items:center;justify-content:center;gap:7px;font-size:11.5px;letter-spacing:.16em;color:#C9B3F2}
.ea-finalHT{font-size:clamp(24px,6.4vw,32px);line-height:1.08;margin:8px 0 6px;text-transform:none;letter-spacing:-.015em;font-weight:800}
.ea-finalHX{margin:0;font-size:14.5px;color:#DCD3EE}
@keyframes ea-finalIn{from{opacity:0;transform:scale(.9) translateY(10px)}}
@keyframes ea-camBarra{from{width:0}}

.ea-ops{margin-top:18px;display:flex;flex-direction:column;gap:8px}
.ea-op{display:block;width:100%;text-align:left;background:transparent;color:var(--tintaPapel);
  border:1px solid rgba(61,61,61,.32);padding:11px 13px;font:inherit;font-size:14.5px;cursor:pointer;
  transition:background .15s,border-color .15s,transform .12s}
.ea-op:hover:not(:disabled){background:rgba(185,83,42,.14);border-color:var(--cobre);transform:translateX(3px)}
.ea-op:focus-visible{outline:2px solid var(--cobre);outline-offset:2px}
.ea-op:disabled{cursor:default;transform:none}
.ea-op.ok{border-color:#3D8A49;background:rgba(62,107,60,.15)}
.ea-op.no{border-color:var(--rojo);background:rgba(178,59,39,.13)}
.ea-opN{font-size:11px;letter-spacing:.16em;color:var(--gris);margin-right:9px}
.ea-opTag{display:block;font-size:11px;letter-spacing:.14em;color:var(--gris);margin-top:5px}
.ea-opSolo{display:inline-block;font-size:9.5px;letter-spacing:.14em;color:var(--cobre);
  border:1px solid var(--cobre);padding:1px 6px;margin-left:8px;vertical-align:middle}

/* Una opcion que no te alcanza se ve, y se ve POR QUE no te alcanza. No
   se esconde: enterarte de lo que te estas perdiendo es justo lo que
   hace que quieras tener mas energia o mas criterio la proxima vez. */
/* Salia una cada tres años de juego y pasaba desapercibida: opacidad al
   52% y un borde punteado gris sobre fondo gris. Ahora se ve que esta
   cerrada, y por que, sin tener que buscarlo. */
.ea-op.sinfuerza{opacity:1;cursor:not-allowed;border-style:dashed;
  border-color:rgba(178,59,39,.42);background:rgba(178,59,39,.05);
  color:rgba(61,61,61,.55)}
.ea-op.sinfuerza:hover{transform:none;background:rgba(178,59,39,.05)}
.ea-op.sinfuerza .ea-opN{color:rgba(155,56,38,.6)}
/* Lo que mueve cada opcion, en simbolos y con color: verde lo que suma,
   rojo lo que cuesta. Antes era una linea de texto gris donde ganar red
   y perder energia pesaban visualmente lo mismo. */
.ea-efs{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}
.ea-ef{display:inline-flex;align-items:center;gap:3px;font-size:12px;
  padding:3px 9px;border-radius:11px;border:1px solid;line-height:1.5}
/* los signos mandan sobre el icono: son los que dicen cuanto */
.ea-efS{font-size:13.5px;font-weight:700;letter-spacing:-.06em}
.ea-ef.pos{color:#2E7A3D;border-color:rgba(62,138,73,.45);background:rgba(79,160,92,.1)}
.ea-ef.neg{color:#9B3826;border-color:rgba(178,59,39,.4);background:rgba(178,59,39,.08)}
.ea-op:disabled .ea-ef{filter:grayscale(.55)}

.ea-opCandado{display:inline-flex;align-items:center;gap:5px;font-size:11px;
  letter-spacing:.06em;border-radius:11px;background:rgba(178,59,39,.1);
  font-variant-numeric:tabular-nums;color:#9B3826;
  border:1px solid rgba(178,59,39,.45);padding:3px 9px;margin-left:9px;vertical-align:middle;
  white-space:nowrap}

.ea-sello{position:absolute;top:14px;right:18px;transform:rotate(-11deg);
  border:3px solid var(--cobre);color:var(--cobre);padding:4px 11px;font-size:14px;
  letter-spacing:.14em;opacity:.85;animation:ea-stamp .3s ease-out}
.ea-sello.med{border-color:var(--gris);color:var(--gris)}
.ea-sello.mal{border-color:var(--rojo);color:var(--rojo)}
@keyframes ea-stamp{from{transform:rotate(-11deg) scale(1.7);opacity:0}to{transform:rotate(-11deg) scale(1);opacity:.85}}

.ea-res{border-top:1px dashed rgba(61,61,61,.4);margin-top:16px;padding-top:13px}
.ea-cambios{display:flex;flex-wrap:wrap;gap:6px;margin-top:11px}
.ea-chip{font-size:12px;padding:3px 9px;border:1px solid rgba(61,61,61,.3)}
.ea-chip.pos{color:#3D8A49;border-color:#3D8A49}
.ea-chip.neg{color:#8A2E1E;border-color:#8A2E1E}

.ea-noti{background:rgba(61,61,61,.07);border-left:3px solid var(--tintaPapel);padding:10px 12px;margin-top:14px}
.ea-notiK{font-size:10.5px;letter-spacing:.2em;color:var(--gris)}
.ea-notiT{font-size:14.5px;color:#3D3D3D;margin-top:3px;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700;letter-spacing:.02em}

.ea-btn{background:var(--tintaPapel);color:var(--papel);border:none;padding:11px 20px;font:inherit;
  font-size:13px;letter-spacing:.14em;cursor:pointer;margin-top:16px;border-radius:2px;
  transition:background .15s,transform .12s;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-btn:hover:not(:disabled){background:var(--cobre)}
.ea-btn:active:not(:disabled){transform:translateY(1px)}
.ea-btn:disabled{opacity:.4;cursor:not-allowed}
.ea-btnO{background:transparent;color:var(--tintaPapel);border:1px solid var(--borde);padding:11px 20px;
  font:inherit;font-size:13px;letter-spacing:.14em;cursor:pointer;border-radius:2px;
  transition:border-color .15s,color .15s;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-btnO:hover{border-color:var(--cobre);color:var(--cobre)}

.ea-tit{font-size:13px;padding:6px 0;border-bottom:1px dotted var(--borde);display:flex;gap:9px}
.ea-titQ{color:var(--cobre);flex-shrink:0;font-size:11.5px}

/* ---- minijuegos ---- */
.ea-jw{margin-top:16px}
.ea-jinfo{display:flex;justify-content:space-between;gap:10px;font-size:11.5px;letter-spacing:.14em;color:var(--gris);margin-bottom:11px}
.ea-pista{background:rgba(61,61,61,.06);border-left:3px solid var(--cobre);padding:9px 12px;font-size:13.5px;color:#3D3D3D;margin-bottom:15px}

.ea-pbar{position:relative;height:42px;background:rgba(61,61,61,.08);border:1px solid rgba(61,61,61,.25);overflow:hidden}
.ea-pzona{position:absolute;top:0;bottom:0;background:rgba(79,160,92,.35);border-left:1px solid #3D8A49;border-right:1px solid #3D8A49}
.ea-pcursor{position:absolute;top:-3px;bottom:-3px;width:3px;background:var(--tintaPapel)}

.ea-celdas{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:260px}
.ea-celda{aspect-ratio:1/1;background:rgba(61,61,61,.08);border:1px solid rgba(61,61,61,.25);cursor:pointer;
  transition:background .12s;display:flex;align-items:center;justify-content:center;
  font-family:var(--f-dis);font-size:36px;color:var(--tintaPapel);line-height:1}
.ea-celda.on{background:var(--cobre)}
.ea-celda.mal{background:var(--rojo)}
.ea-celda.gana{background:rgba(79,160,92,.4)}

.ea-nums{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.ea-num{background:rgba(61,61,61,.07);border:1px solid rgba(61,61,61,.22);padding:10px 3px;cursor:pointer;
  font-size:13.5px;text-align:center;color:var(--tintaPapel)}
.ea-num:hover{border-color:var(--cobre)}

.ea-mult{font-size:50px;line-height:1;color:var(--tintaPapel)}
.ea-jwCentro{text-align:center}
.ea-jwCentro .ea-mult{font-size:clamp(56px,16vw,92px);margin-top:10px}
.ea-suerteMeta{font-size:11.5px;color:var(--gris);margin-top:6px}
.ea-suerteHist{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:12px}
.ea-suerteH{font-size:12px;padding:2px 8px;border:1px solid rgba(61,61,61,.25)}
.ea-suerteH.ok{color:#2F7A3D;border-color:#2F7A3D}
.ea-suerteH.mal{color:var(--rojo);border-color:var(--rojo)}
.ea-fila2{display:flex;gap:9px;flex-wrap:wrap;margin-top:13px}
.ea-qtxt{font-size:16.5px;color:#3D3D3D;margin:0 0 13px}
.ea-expl{font-size:13.5px;color:var(--gris);margin-top:11px;border-left:2px solid var(--cobre);padding-left:10px}

.ea-luz{height:120px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(61,61,61,.25);
  background:rgba(61,61,61,.06);font-size:22px;text-align:center;padding:14px;line-height:1.2;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700;color:#3D3D3D}
.ea-luz.lista{background:rgba(79,160,92,.35);border-color:#3D8A49}
.ea-luz.roja{background:rgba(178,59,39,.28);border-color:var(--rojo)}

.ea-ordenL{display:flex;flex-direction:column;gap:7px}
.ea-ordenI{border:1px solid rgba(61,61,61,.28);padding:10px 12px;cursor:pointer;font-size:14px;
  display:flex;justify-content:space-between;gap:10px;align-items:center;background:transparent;color:var(--tintaPapel);
  text-align:left;font:inherit;width:100%}
.ea-ordenI:hover:not(:disabled){border-color:var(--cobre)}
.ea-ordenI.hecho{background:rgba(62,107,60,.16);border-color:#3D8A49;cursor:default}
.ea-ordenI.err{background:rgba(178,59,39,.16);border-color:var(--rojo)}
.ea-ordenN{font-size:11px;letter-spacing:.14em;color:var(--gris)}

.ea-portada{max-width:680px;margin:5vh auto;text-align:left}
.ea-h1{font-size:clamp(44px,11vw,84px);line-height:.9;color:var(--tintaPapel);margin:0}
.ea-lede{color:var(--gris);margin:18px 0 26px;font-size:16px;max-width:56ch}
.ea-regla{height:1px;background:var(--borde);margin:24px 0}
.ea-final{font-size:33px;color:var(--tintaPapel);line-height:1.1;margin:0 0 12px}
.ea-cifras{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:15px}
/* en la portada, dos por dos: con cuatro textos largos, auto-fit dejaba
   tres arriba y uno huérfano abajo, o se montaban en pantallas estrechas */
.ea-cifras.ea-cifrasPortada{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 24px}
@media (max-width:460px){.ea-cifras.ea-cifrasPortada{grid-template-columns:1fr}}
.ea-cifraV{overflow-wrap:break-word}
.ea-cifraK{font-size:11px;color:var(--gris);letter-spacing:.18em;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-cifraV{font-size:20px;color:var(--tintaPapel)}
.ea-cifraD{font-size:12.5px;line-height:1.45;color:var(--gris);margin-top:5px}
`;

const CSS5 = `
/* --- memoria por colores --- */
.ea-celdaC{aspect-ratio:1/1;border:2px solid;cursor:pointer;transition:background .12s,transform .1s,border-color .12s;
  display:flex;align-items:flex-end;justify-content:center;padding:6px 3px;font:inherit}
.ea-celdaC:disabled{cursor:default}

/* --- vidas / intentos restantes --- */
.ea-vidas{display:flex;gap:6px;margin-top:11px}
.ea-vida{width:26px;height:5px;background:rgba(61,61,61,.18)}
.ea-vida.viva{background:var(--cobre)}

/* --- la clase de la cátedra --- */
.ea-claseT{font-size:23px;line-height:1.1;margin:4px 0 10px;color:#262626;
  font-family:var(--f-dis);text-transform:uppercase;letter-spacing:.02em;font-weight:700}
.ea-ej{background:rgba(185,83,42,.1);border-left:3px solid var(--cobre);padding:10px 13px;margin-top:14px}
.ea-ejX{font-size:14px;color:#3D3D3D;margin-top:3px;font-family:var(--f-num);line-height:1.5}

/* --- la sesión de trading --- */
.ea-estado{margin-top:12px;padding:11px;text-align:center;font-size:15px;letter-spacing:.16em;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700;border:2px solid}
.ea-estado.dentro{background:rgba(79,160,92,.28);border-color:#3D8A49;color:#1F5A2E}
.ea-estado.fuera{background:rgba(61,61,61,.07);border-color:rgba(61,61,61,.3);color:#6B6B6B}
.ea-leyenda{display:flex;gap:16px;flex-wrap:wrap;margin-top:6px;font-size:11.5px;color:var(--gris)}
.ea-leyenda span{display:flex;align-items:center;gap:6px}
.ea-lineaL{display:inline-block;width:20px;height:0;border-top:2px solid #3D3D3D}
.ea-lineaD{display:inline-block;width:20px;height:0;border-top:2px dashed var(--cobre)}
.ea-marcador{display:grid;grid-template-columns:repeat(auto-fit,minmax(115px,1fr));gap:11px;margin-top:13px;
  border-top:1px dashed rgba(61,61,61,.35);padding-top:11px}
.ea-marcaV{font-size:19px;line-height:1.1;margin-top:2px}

/* --- los dos escenarios de la estructura --- */
.ea-escen{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-top:14px}
.ea-escenC{border:1px solid rgba(61,61,61,.28);padding:11px 13px}
.ea-escenC.bien{border-color:#3D8A49;background:rgba(79,160,92,.1)}
.ea-escenC.mal{border-color:var(--rojo);background:rgba(178,59,39,.08)}
.ea-escenX{font-size:12.5px;color:#6B6B6B;margin-top:4px;line-height:1.45}
.ea-escenV{font-size:27px;line-height:1;margin:7px 0 2px;color:#3D3D3D}

/* --- pantallas de configuración --- */
.ea-opcion{border:1px solid var(--borde);background:var(--papel);padding:14px 16px;margin-bottom:10px;
  cursor:pointer;width:100%;text-align:left;font:inherit;color:var(--tintaPapel);transition:border-color .15s,background .15s}
.ea-opcion:hover{border-color:var(--cobre)}
.ea-opcion.on{border-color:var(--cobre);background:rgba(185,83,42,.09)}
.ea-opcionN{font-size:19px;color:var(--tintaPapel);
  font-family:var(--f-dis);text-transform:uppercase;letter-spacing:.04em;font-weight:700}
.ea-opcionD{font-size:13.5px;color:var(--gris);margin-top:6px;line-height:1.5}
.ea-opcionM{font-size:12px;color:var(--cobre);margin-top:6px}

/* --- cómo vives: el medidor del tren de vida --- */
.ea-vidaCab{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.ea-vidaN{font-size:21px;color:var(--tintaPapel);line-height:1.05}
.ea-vidaD{font-size:12.5px;color:var(--gris);margin-top:5px;line-height:1.5}
.ea-vidaCifra{font-size:30px;color:var(--cobre);line-height:1;flex-shrink:0}
.ea-medidor{position:relative;height:8px;background:#041F0E;margin-top:12px;overflow:hidden}
.ea-medidorF{height:100%;background:var(--cobre);transition:width .5s ease}
.ea-medidorT{position:absolute;top:0;bottom:0;width:1px;background:rgba(237,237,232,.35)}
.ea-medidorE{display:flex;justify-content:space-between;gap:4px;margin-top:5px;font-size:9.5px;
  letter-spacing:.06em;color:var(--gris);text-transform:uppercase;
  font-family:var(--f-dis);font-weight:700}
.ea-medidorE span.on{color:var(--cobre)}

/* --- etiquetas de consecuencia en cada compra --- */
.ea-etqs{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}
.ea-etq{font-size:10.5px;letter-spacing:.06em;padding:2px 7px;border:1px solid var(--borde);
  color:var(--gris);white-space:nowrap}
.ea-etq.vida{border-color:var(--cobre);color:var(--cobre)}
.ea-etq.act{border-color:#3D8A49;color:var(--verde)}
.ea-etq.con{border-color:#7A392E;color:#C4756A}
.ea-etq.cost{border-color:#6B6B6B;color:#A99C86}

/* --- el camino del año --- */
.ea-curvaWrap{position:relative;margin:12px 0 4px;touch-action:pan-y}
/* sin overflow visible: era lo que dejaba salir las cifras del eje
   fuera del lienzo por la izquierda */
.ea-curva{width:100%;height:auto;display:block}
.ea-cHitoT{stroke:rgba(61,61,61,.30);stroke-width:1;stroke-dasharray:2 2}
.ea-cHitoN{font-family:var(--f-dis);font-size:9px;font-weight:700;
  letter-spacing:.06em;text-transform:uppercase;fill:var(--gris)}
.ea-hitosL{display:flex;flex-direction:column;gap:3px;margin-top:9px;
  border-top:1px dotted rgba(61,61,61,.3);padding-top:8px}
.ea-hitoF{display:flex;align-items:baseline;gap:7px;font-size:12px;color:#6B6B6B}
.ea-hitoD{width:7px;height:7px;flex-shrink:0;transform:rotate(45deg);align-self:center}
.ea-hitoM{font-size:10.5px;color:var(--gris);text-transform:uppercase;letter-spacing:.08em;
  flex-shrink:0;width:24px}
.ea-hitoT{flex:1;line-height:1.35}
.ea-hitoC{font-size:11.5px;flex-shrink:0;font-variant-numeric:tabular-nums}
.ea-cRejilla{stroke:rgba(61,61,61,.10);stroke-width:1}
.ea-cPartida{stroke:rgba(61,61,61,.45);stroke-width:1;stroke-dasharray:3 3}
.ea-cCaida{fill:rgba(160,53,36,.09)}
.ea-cCruz{stroke:rgba(61,61,61,.35);stroke-width:1}
/* Los ejes viven fuera del SVG, así que su tamaño no depende de cuánto
   se escale el gráfico: se leen igual en un móvil y en un monitor. */
.ea-ejeY{position:absolute;left:0;text-align:right;transform:translateY(-50%);
  font-size:10.5px;color:var(--gris);font-variant-numeric:tabular-nums;
  pointer-events:none;padding-right:6px;line-height:1;white-space:nowrap}
.ea-ejeX{position:absolute;bottom:0;font-size:10px;color:var(--gris);letter-spacing:.06em;
  pointer-events:none;line-height:1;white-space:nowrap;text-transform:uppercase}
.ea-ejeX.ea-der{text-align:right}
.ea-curvaTip{position:absolute;top:-2px;transform:translateX(-50%);pointer-events:none;
  background:#3D3D3D;color:#F7F7F5;font-size:11.5px;padding:4px 8px;white-space:nowrap;
  font-variant-numeric:tabular-nums;display:flex;gap:7px;align-items:baseline;z-index:2}
.ea-curvaTipM{color:#A9C2B0;font-size:10px;letter-spacing:.1em;text-transform:uppercase}
.ea-curvaTipD{font-size:11px}
.ea-curvaPie{font-size:12.5px;color:#6B6B6B;line-height:1.5;margin-top:2px}

/* --- las dos constantes vitales, siempre a la vista --- */
.ea-signos{font-size:11.5px;margin-top:3px;display:flex;gap:12px;justify-content:flex-end;color:var(--tenue)}
.ea-signos .ojo{color:var(--cobre)}
.ea-signos .mal{color:var(--rojo)}

/* --- las señales de un negocio --- */
.ea-dealS{display:flex;flex-wrap:wrap;gap:5px;margin:8px 0 6px}
.ea-sen{display:flex;flex-direction:column;gap:1px;border:1px solid var(--borde);padding:3px 8px;min-width:66px}
.ea-sen.bien{border-color:#3D8A49}
.ea-sen.mal{border-color:#7A392E}
.ea-senK{font-size:9px;letter-spacing:.1em;color:var(--tenue);text-transform:uppercase;
  font-family:var(--f-dis);font-weight:700}
.ea-senV{font-size:12.5px;color:var(--tintaPapel)}
.ea-sen.bien .ea-senV{color:var(--verde)}
.ea-sen.mal .ea-senV{color:#C4756A}
.ea-deal{border:1px solid rgba(61,61,61,.28);padding:11px 13px;margin-bottom:9px;background:rgba(61,61,61,.03)}
.ea-deal.sel{border-color:var(--cobre);background:rgba(185,83,42,.09)}
.ea-deal.gana{border-color:#3D8A49;background:rgba(79,160,92,.11)}
.ea-deal .ea-sen{border-color:rgba(61,61,61,.25)}
.ea-deal .ea-senK{color:var(--gris)}
.ea-deal .ea-senV{color:#3D3D3D}
.ea-deal .ea-sen.bien{border-color:#3D8A49}
.ea-deal .ea-sen.bien .ea-senV{color:#2E7A3D}
.ea-deal .ea-sen.mal{border-color:var(--rojo)}
.ea-deal .ea-sen.mal .ea-senV{color:#8A2E1E}
.ea-dealR{font-size:12px;color:var(--gris);margin-top:6px;letter-spacing:.04em}

/* --- el inventario del balance final --- */
.ea-invCab,.ea-invF,.ea-invT{display:grid;grid-template-columns:1fr auto auto auto;gap:12px;align-items:baseline}
.ea-invCab{font-size:10px;letter-spacing:.14em;color:var(--gris);padding-bottom:6px;
  border-bottom:1px solid var(--borde);margin-bottom:4px}
.ea-invF{font-size:13px;padding:6px 0;border-bottom:1px dotted var(--borde);color:var(--tintaPapel)}
.ea-invN{line-height:1.35}
.ea-invP{display:block;font-size:10.5px;color:var(--gris);text-align:right}
.ea-invT{font-size:13px;padding-top:9px;margin-top:4px;border-top:1px solid var(--borde);color:var(--tintaPapel)}
@media(max-width:520px){
  .ea-invCab{display:none}
  .ea-invF,.ea-invT{grid-template-columns:1fr auto;row-gap:2px}
}

/* --- el aviso de entrada --- */
.ea-aviso{display:flex;flex-direction:column;gap:2px;margin-top:22px;
  border-left:2px solid var(--borde);padding-left:16px}
.ea-avisoB{padding:11px 0;border-bottom:1px dotted var(--borde)}
.ea-avisoB:last-child{border-bottom:none}
.ea-avisoK{font-size:11.5px;letter-spacing:.16em;color:var(--cobre);margin-bottom:5px}
.ea-avisoB p{margin:0;font-size:14.5px;color:var(--tintaPapel);line-height:1.6;max-width:62ch}
.ea-avisoB strong{color:#262626}

/* --- botones secundarios sobre papel ---
   .ea-mini nació para el panel oscuro: texto hueso #EDEDE8 sobre
   fieltro da 9,6:1. Dentro del memorando el fondo es papel y ese mismo
   color cae a 1,29:1, o sea invisible. Se corrige por contexto y no
   botón por botón, para que ningún minijuego futuro herede el problema. */
.ea-memo .ea-mini{border-color:rgba(61,61,61,.42);color:var(--tintaPapel)}
.ea-memo .ea-mini:hover:not(:disabled){border-color:var(--cobre);color:#262626;background:rgba(185,83,42,.13)}
.ea-memo .ea-mini:disabled{opacity:.45}

/* el de "explícame" es una invitación, no un control secundario:
   se lee a tamaño normal y sin versalitas apretadas */
.ea-explicame{font-size:12.5px;letter-spacing:.06em;text-transform:none;padding:8px 14px}

/* --- el titular: lo único que se lee sin abrir nada --- */
.ea-titular{border-top:2px solid var(--tintaPapel);border-bottom:1px dashed rgba(61,61,61,.35);
  padding:12px 0 13px;margin-top:14px}
.ea-panel .ea-titular,.ea-modal .ea-titular{border-top-color:var(--borde);border-bottom-color:var(--borde)}
.ea-titularK{font-size:10.5px;letter-spacing:.2em;color:var(--gris)}
.ea-titularV{font-size:31px;line-height:1.05;color:#262626;margin:3px 0 6px}
.ea-titularL{display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;color:var(--gris)}
.ea-titularA{font-size:15px;color:var(--cobre);margin-top:8px}

/* --- secciones plegables: cerradas enseñan su cifra --- */
.ea-plegs{margin-top:14px;border-top:1px dotted rgba(61,61,61,.32)}
.ea-panel .ea-plegs,.ea-modal .ea-plegs{border-top-color:var(--borde)}
.ea-pleg{border-bottom:1px dotted rgba(61,61,61,.32)}
.ea-panel .ea-pleg,.ea-modal .ea-pleg{border-bottom-color:var(--borde)}
.ea-plegB{display:grid;grid-template-columns:auto 1fr auto;align-items:baseline;gap:10px;width:100%;
  background:transparent;border:none;padding:11px 2px;cursor:pointer;text-align:left;font:inherit}
.ea-plegB:hover .ea-plegT{color:var(--cobre)}
.ea-plegF{font-size:15px;color:var(--gris);line-height:1;width:12px}
.ea-plegT{font-size:12.5px;letter-spacing:.08em;color:#3D3D3D}
.ea-plegR{font-size:13px;color:var(--gris);white-space:nowrap;font-variant-numeric:tabular-nums}
.ea-plegC{padding:2px 0 15px;animation:ea-abre .16s ease-out}

/* --- los avisos de la guía --- */
.ea-guia{border:1px solid var(--cobre);background:rgba(185,83,42,.09);padding:12px 15px;margin-top:16px;
  display:grid;grid-template-columns:1fr auto;gap:4px 14px;align-items:center;animation:ea-abre .2s ease-out}
.ea-guiaK{grid-column:1;font-size:10px;letter-spacing:.22em;color:var(--cobre)}
.ea-guiaT{grid-column:1;font-size:16px;color:#262626;line-height:1.15}
.ea-guiaX{grid-column:1;font-size:13.5px;color:var(--tintaPapel);line-height:1.5;max-width:70ch}
.ea-guiaB{grid-column:2;grid-row:1 / span 3;align-self:center;background:var(--cobre);border:none;color:#20120A;
  font:inherit;font-size:11px;letter-spacing:.14em;padding:9px 15px;cursor:pointer;text-transform:uppercase;
  font-family:var(--f-dis);font-weight:700;white-space:nowrap}
.ea-guiaB:hover{background:var(--papel)}
@media(max-width:560px){
  .ea-guia{grid-template-columns:1fr}
  .ea-guiaB{grid-column:1;grid-row:auto;justify-self:start;margin-top:8px}
}

/* --- el tablero, que ya no estorba --- */
.ea-grid.solo{grid-template-columns:1fr}

/* Las secciones dejan de robarle la mitad de la pantalla a la decision:
   se abren encima, y al cerrarlas el jugador vuelve exactamente a donde
   estaba. La decision es lo principal y ahora se ve asi. */
.ea-modalFondo{position:fixed;inset:0;background:rgba(5,13,16,.84);z-index:60;
  display:flex;align-items:flex-start;justify-content:center;padding:22px 14px;overflow-y:auto}
.ea-modal{background:var(--papel);border:1px solid var(--borde);width:100%;max-width:580px;
  border-radius:4px;overflow:hidden;
  box-shadow:0 20px 64px rgba(0,51,24,.45)}
.ea-modalCab{display:flex;justify-content:space-between;align-items:center;gap:12px;
  padding:12px 15px;border-bottom:1px solid var(--borde);position:sticky;top:0;
  background:var(--papel);z-index:2}
.ea-modalT{font-size:12px;letter-spacing:.2em;color:var(--cobre)}
.ea-modalX{background:transparent;border:1px solid var(--borde);color:var(--gris);
  width:31px;height:31px;cursor:pointer;font:inherit;font-size:14px;line-height:1;flex-shrink:0}
.ea-modalX:hover:not(:disabled){border-color:var(--cobre);color:var(--cobre)}
.ea-modalX:disabled{opacity:.35;cursor:default}
.ea-modalCuerpo{padding:14px 15px 18px}

/* la ficha que explica un sistema recien abierto */
.ea-nuevoK{font-size:10.5px;letter-spacing:.22em;color:var(--cobre);margin-bottom:7px}
.ea-nuevoT{font-size:27px;line-height:1.08;color:#262626;margin-bottom:9px}
.ea-nuevoX{font-size:14px;line-height:1.6;color:var(--tintaPapel);margin-bottom:14px}
.ea-nuevoP{list-style:none;padding:0;margin:0 0 4px}
.ea-nuevoP li{position:relative;padding-left:19px;margin-bottom:10px;font-size:13px;
  line-height:1.55;color:var(--gris)}
.ea-nuevoP li:before{content:"";position:absolute;left:0;top:7px;width:8px;height:8px;
  background:var(--cobre)}

/* --- el registro compartido de carreras cerradas --- */
.ea-regCab{display:grid;grid-template-columns:24px 1fr auto auto;gap:10px;
  padding:0 0 7px;border-bottom:1px solid var(--borde);
  font-size:10px;letter-spacing:.14em;color:var(--gris)}
.ea-regFila{display:grid;grid-template-columns:24px 1fr auto auto;gap:10px;align-items:baseline;
  padding:9px 0;border-bottom:1px dotted var(--borde);font-size:13.5px}
.ea-regFila:last-child{border-bottom:none}
.ea-regP{font-family:var(--f-num);font-size:12px;color:var(--gris);
  font-variant-numeric:tabular-nums}
.ea-regFila.podio .ea-regP{color:var(--cobre)}
.ea-regN{color:var(--tintaPapel);line-height:1.3}
.ea-regC{display:block;font-size:11.5px;color:var(--gris)}
.ea-regV{font-family:var(--f-num);color:var(--tintaPapel);text-align:right;
  white-space:nowrap;font-variant-numeric:tabular-nums}
.ea-regM{font-family:var(--f-num);font-size:12px;color:var(--cobre);
  text-align:right;white-space:nowrap;min-width:3ch}
.ea-regFila.tuya{background:rgba(185,83,42,.11);border-left:2px solid var(--cobre);
  padding-left:8px;margin-left:-10px}
.ea-regVacio{padding:22px 0;color:var(--gris);font-size:13.5px}
.ea-regNombre{width:100%;background:var(--papel2);border:1px solid var(--borde);color:var(--tintaPapel);
  font-family:var(--f-num);font-size:14px;padding:9px 11px;border-radius:0;margin-top:6px}

.ea-panelAb{animation:ea-abre .18s ease-out}
@keyframes ea-abre{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
.ea-cerrar{display:block;width:100%;background:transparent;border:1px solid var(--borde);
  color:var(--gris);font:inherit;font-size:10.5px;letter-spacing:.14em;padding:7px;margin-bottom:14px;
  cursor:pointer;text-transform:uppercase;font-family:var(--f-dis);font-weight:700}
.ea-cerrar:hover{border-color:var(--cobre);color:var(--cobre)}
.ea-tabs{margin-top:16px}

/* --- quién eres --- */
.ea-campoK{font-size:11px;letter-spacing:.2em;color:var(--gris);display:block;margin-bottom:7px}
.ea-campo{width:100%;max-width:420px;background:var(--papel2);border:1px solid var(--borde);
  color:var(--tintaPapel);font-size:19px;padding:11px 13px;letter-spacing:.04em}
.ea-campo::placeholder{color:var(--gris);opacity:.7;letter-spacing:.02em}
.ea-campo:focus{outline:2px solid var(--cobre);outline-offset:2px;border-color:var(--cobre)}
.ea-generos{display:flex;gap:8px;flex-wrap:wrap}
.ea-generos .ea-mini.on{border-color:var(--cobre);color:var(--tintaPapel);background:rgba(185,83,42,.15)}

/* --- volver atrás en la configuración --- */
/* display:block porque es un <button>, o sea inline: sin esto el boton
   que venga detras se le pega al lado en la misma linea. */
.ea-atras{display:block;background:transparent;border:none;color:var(--gris);font:inherit;font-size:11.5px;
  letter-spacing:.14em;padding:6px 0;margin-bottom:10px;cursor:pointer;text-transform:uppercase;
  text-align:left;font-family:var(--f-dis);font-weight:700}
.ea-atras:hover{color:var(--cobre)}
.ea-rastro{font-size:12px;color:var(--cobre);margin:6px 0 14px;letter-spacing:.04em}

/* --- glosario del modo aprendiz --- */
.ea-glos{background:rgba(62,107,60,.1);border-left:3px solid #3D8A49;padding:10px 13px;margin-top:12px}
.ea-glosK{font-size:10.5px;letter-spacing:.2em;color:var(--gris);
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-glosT{font-size:14.5px;color:#3D3D3D;margin-top:3px;
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700;letter-spacing:.02em}
.ea-glosX{font-size:13.5px;color:#3D3D3D;margin-top:4px;line-height:1.5}

/* --- banderas rojas con explicación --- */
.ea-docK{font-size:10.5px;letter-spacing:.18em;color:var(--gris);
  font-family:var(--f-dis);text-transform:uppercase;font-weight:700}
.ea-checkX{display:block;font-size:12.5px;line-height:1.5;color:#6B6B6B;margin-top:6px;
  border-top:1px dotted rgba(61,61,61,.3);padding-top:6px}
.ea-checkR{display:block;font-size:10.5px;letter-spacing:.14em;color:var(--gris);margin-bottom:3px}
.ea-checkR.roja{color:#8A2E1E}

/* --- la ficha de familia --- */
.ea-fam{display:flex;gap:8px;flex-wrap:wrap;margin-top:4px}
.ea-famC{border:1px solid var(--borde);padding:4px 9px;font-size:11.5px;color:var(--gris)}
`;

