/* El contexto de una pregunta, por orden: el tema del que salió, la
   pista escrita a mano, o el término del glosario que aparezca en el
   enunciado. Si no hay ninguno, no se ofrece explicación. */
const contextoDe = (p) => {
  if (!p) return null;
  const tm = p.tema ? TEMAS.find((x) => x.id === p.tema) : null;
  if (tm) return { t: tm.n, x: tm.x, ej: tm.ej };
  if (p.pista) return { t: "Lo que hace falta saber", x: p.pista };
  const txt = String(p.q || "");
  for (let i = 0; i < GLOS_EN_TEXTO.length; i++) {
    if (!GLOS_EN_TEXTO[i][0].test(txt)) continue;
    const clave = GLOS_EN_TEXTO[i][1];
    const g = GLOSARIO[clave];
    if (g) return { t: g.n, x: g.x };
    /* la clave también puede ser un tema entero */
    const tm2 = TEMAS.find((x) => x.id === clave);
    if (tm2) return { t: tm2.n, x: tm2.x, ej: tm2.ej };
  }
  return null;
};

/* Qué palabras hay que haber entendido antes de jugar cada modo.
   En modo aprendiz se muestran como fichas antes de empezar; en modo
   analista se dan por sabidas. */
const GLOS_JUEGO = {
  catedra: ["interesCompuesto", "riesgo"],
  quiz: ["rendimiento", "riesgo", "tasaEfectiva"],
  trading: ["accion", "volatilidad", "rendimiento"],
  estructura: ["apalancamiento", "ebitda"],
  banderas: ["riesgo", "liquidez"],
  carril: ["accion", "bono", "liquidez"],
  pares: ["cartera", "diversificar"],
  subasta: ["riesgo", "apalancamiento"],
  calculo: ["rendimiento", "interesCompuesto"],
  semaforo: ["riesgo", "volatilidad"],
  orden: ["bono", "liquidez"],
  anclaje: ["riesgo"],
  suerte: ["volatilidad", "riesgo"],
  precision: ["volatilidad"],
  ojo: ["riesgo"],
  memoria: ["cartera"],
  reaccion: ["volatilidad"],
  tresraya: ["riesgo"],
  cuatro: ["riesgo"],
};
const TEMA_DE = (id) => TEMAS.find((x) => x.id === id) || null;

/* Cinco minijuegos usan divs como zona de clic porque su diseño no
   admite un <button> sin romperse el layout. Esto los vuelve operables
   con teclado sin tocar una línea de CSS: foco, Enter y espacio. */
const pulsable = (fn, rotulo, apagado) => ({
  role: "button",
  tabIndex: apagado ? -1 : 0,
  "aria-label": rotulo || undefined,
  "aria-disabled": apagado ? "true" : undefined,
  onClick: apagado ? undefined : fn,
  onKeyDown: apagado ? undefined : (e) => {
    if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") { e.preventDefault(); fn(); }
  },
});

/* ============================ MINIJUEGOS ============================ */

function JuegoPrecision({ ayuda, onFin }) {
  const ancho = clamp(11 + ayuda * 0.15, 11, 28);
  const [ronda, setRonda] = useState(0);
  const [pos, setPos] = useState(0);
  const [zona, setZona] = useState(() => 22 + Math.random() * 56);
  const [hits, setHits] = useState(0);
  const [pausa, setPausa] = useState(false);
  const [aviso, setAviso] = useState(null);
  const dir = useRef(1);
  const anchoR = ancho * Math.pow(0.78, ronda);
  const vel = 1 + ronda * 0.5;

  useEffect(() => {
    if (pausa) return;
    const id = setInterval(() => {
      setPos((p) => {
        let n = p + dir.current * vel;
        if (n >= 100) { n = 100; dir.current = -1; }
        if (n <= 0) { n = 0; dir.current = 1; }
        return n;
      });
    }, 16);
    return () => clearInterval(id);
  }, [pausa, vel]);

  const fijar = () => {
    setPausa(true);
    const dentro = Math.abs(pos - zona) <= anchoR / 2;
    const h = hits + (dentro ? 1 : 0);
    setHits(h);
    setAviso(dentro ? "Dentro del rango" : "Fuera por " + Math.abs(pos - zona).toFixed(1) + " puntos");
    setTimeout(() => {
      if (ronda >= 2) onFin(h >= 3 ? "exito" : h === 2 ? "parcial" : "fallo");
      else {
        setRonda(ronda + 1); setZona(22 + Math.random() * 56);
        setPos(0); dir.current = 1; setAviso(null); setPausa(false);
      }
    }, 900);
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Intento {ronda + 1} de 3</span><span>Aciertos {hits}</span></div>
      <div className="ea-pbar">
        <div className="ea-pzona" style={{ left: (zona - anchoR / 2) + "%", width: anchoR + "%" }} />
        <div className="ea-pcursor" style={{ left: pos + "%" }} />
      </div>
      <div style={{ minHeight: 22, marginTop: 8, fontSize: 13.5, color: "#6B6B6B" }}>{aviso}</div>
      <button className="ea-btn" onClick={fijar} disabled={pausa}>Fijar</button>
    </div>
  );
}

/* ---- Peinar el legajo · memoria de trabajo ----
   Reescrito: cada casilla tiene su propio color y su propio nombre, así
   que la secuencia se recuerda como "cobre, verde, vino" y no como tres
   cuadrados grises indistinguibles. Y ahora hay tres vidas: fallar una
   vez ya no termina la partida, te repiten la secuencia y sigues. */

const COLORES_MEM = [
  { c: "#B9532A", n: "Cobre" },
  { c: "#4FA05C", n: "Verde" },
  { c: "#B23B27", n: "Rojo" },
  { c: "#3E6B8C", n: "Azul" },
  { c: "#8C6BA8", n: "Morado" },
  { c: "#C9A227", n: "Mostaza" },
  { c: "#3F8C86", n: "Turquesa" },
  { c: "#A8556F", n: "Vino" },
  { c: "#7A6A55", n: "Arena" },
];

/* ============================================================
   PEINAR EL LEGAJO, COMO SIMON
   Antes era una sola secuencia de cuatro a siete casillas, disparada de
   golpe desde el primer momento: dificil antes de haber entendido nada.

   Ahora son tres rondas, y cada una repite la anterior ENTERA y añade al
   final. Tres casillas, despues esas mismas tres y una mas, despues esas
   cuatro y dos mas. Lo que ya memorizaste sirve en la ronda siguiente,
   que es lo que hace que se aprenda jugando en vez de fallando.
   ============================================================ */
const RONDAS_MEM = [3, 4, 6];

/* Con buen atributo se tiene una segunda oportunidad por ronda. La
   longitud de cada ronda ya no cambia con la ayuda, asi que es la forma
   de que «te ayuda Memoria 70» siga significando algo. */
const vidasMemDe = (ayuda) => (numero(ayuda, 0) >= 55 ? 2 : 1);

/* Segundos para mirar el tablero antes de que empiece a encenderse. Eran
   ocho cuando la primera secuencia ya era larga; con tres casillas de
   entrada bastan menos, y el boton de saltarla sigue ahi. */
const ESPERA_MEM = 4;

function JuegoMemoria({ ayuda, onFin }) {
  /* La secuencia entera se decide al empezar y cada ronda enseña un trozo
     mas largo de la MISMA: por eso lo memorizado no se tira.
     Sin la misma casilla dos veces seguidas, que se lee como un parpadeo y
     no como dos pasos. El reemplazo es aritmetico y no un bucle de
     reintento: con un Math.random que devuelva siempre lo mismo —que es lo
     que prueba robustez— un «vuelve a tirar» no terminaria nunca. */
  const [seq] = useState(() => {
    const total = RONDAS_MEM[RONDAS_MEM.length - 1];
    const out = [];
    for (let i = 0; i < total; i++) {
      let c = indiceAzar(9);
      if (i > 0 && c === out[i - 1]) c = (c + 1 + indiceAzar(8)) % 9;
      out.push(c);
    }
    return out;
  });
  const VIDAS = vidasMemDe(ayuda);
  const [ronda, setRonda] = useState(0);
  const [idx, setIdx] = useState(0);
  const [on, setOn] = useState(null);
  const [modo, setModo] = useState("listo");
  const [cuenta, setCuenta] = useState(ESPERA_MEM);
  const [paso, setPaso] = useState(0);
  const [err, setErr] = useState(null);
  const [vidas, setVidas] = useState(VIDAS);
  const [aviso, setAviso] = useState(null);
  const largo = RONDAS_MEM[ronda];

  /* la espera de cortesia, solo al principio */
  useEffect(() => {
    if (modo !== "listo") return;
    if (cuenta <= 0) { setModo("ver"); return; }
    const t = setTimeout(() => setCuenta((c) => c - 1), 1000);
    return () => clearTimeout(t);
  }, [modo, cuenta]);

  /* enseña la ronda, casilla por casilla */
  useEffect(() => {
    if (modo !== "ver") return;
    if (idx >= largo) {
      const t = setTimeout(() => { setModo("jugar"); setAviso(null); }, 420);
      return () => clearTimeout(t);
    }
    setOn(seq[idx]);
    const a = setTimeout(() => setOn(null), 460);
    const b = setTimeout(() => setIdx(idx + 1), 700);
    return () => { clearTimeout(a); clearTimeout(b); };
  }, [idx, modo, largo, seq]);

  /* entre ronda y ronda, un respiro y a enseñar la siguiente */
  useEffect(() => {
    if (modo !== "entre") return;
    const t = setTimeout(() => {
      setRonda((r) => r + 1); setPaso(0); setIdx(0); setOn(null); setErr(null);
      setVidas(VIDAS); setAviso(null); setModo("ver");
    }, 1000);
    return () => clearTimeout(t);
  }, [modo]);

  const tocar = (i) => {
    if (modo !== "jugar") return;
    if (i === seq[paso]) {
      const p = paso + 1;
      setPaso(p); setOn(i);
      setTimeout(() => setOn(null), 160);
      if (p >= largo) {
        if (ronda >= RONDAS_MEM.length - 1) {
          setModo("fin");
          setAviso("Las tres rondas");
          setTimeout(() => onFin("exito"), 600);
        } else {
          const extra = RONDAS_MEM[ronda + 1] - largo;
          setModo("entre");
          setAviso("Bien. Ahora " + (extra === 1 ? "una más" : extra + " más") + " al final.");
        }
      }
      return;
    }
    /* fallaste: si queda oportunidad se repite ESTA ronda, si no se acaba */
    const quedan = vidas - 1;
    setErr(i);
    setVidas(quedan);
    if (quedan <= 0) {
      setModo("fin");
      setAviso("Se acabó en la ronda " + (ronda + 1));
      /* dos rondas completas es un resultado a medias; menos, fallo */
      setTimeout(() => onFin(ronda >= 2 ? "parcial" : "fallo"), 750);
      return;
    }
    setModo("pausa");
    setAviso("Ahí no. Te repito esta ronda.");
    setTimeout(() => {
      setErr(null); setPaso(0); setIdx(0); setOn(null); setModo("ver");
    }, 950);
  };

  const rotuloModo = modo === "listo" ? "Mira el tablero"
    : modo === "ver" ? "Memoriza la secuencia"
    : modo === "jugar" ? "Repítela en el mismo orden"
    : modo === "entre" ? "Ronda superada"
    : modo === "pausa" ? "Atento" : "Listo";

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>{rotuloModo}</span>
        <span>
          {modo === "listo"
            ? "empieza en " + cuenta + (cuenta === 1 ? " segundo" : " segundos")
            : "ronda " + (ronda + 1) + " de " + RONDAS_MEM.length + " · " + paso + " de " + largo}
        </span>
      </div>

      {/* las tres rondas como puntos, y cuantas casillas trae cada una */}
      <div className="ea-memRondas">
        {RONDAS_MEM.map((n, r) => (
          <span key={r} className={"ea-memRonda" + (r < ronda ? " hecha" : r === ronda ? " ahora" : "")}>
            {n}
          </span>
        ))}
      </div>

      <Pista>
        Cada casilla tiene su color. Tres rondas: se encienden 3, luego 4 y luego 6.
        Cada ronda repite la anterior entera y añade al final, así que lo que ya
        memorizaste te sirve.
      </Pista>

      <div className="ea-celdas">
        {COLORES_MEM.map((col, i) => {
          const encendida = on === i;
          const fallada = err === i;
          return (
            <button key={i} type="button" className="ea-celdaC" onClick={() => tocar(i)}
              disabled={modo !== "jugar"} aria-label={col.n}
              style={{
                background: fallada ? "var(--rojo)" : (encendida || modo === "listo") ? col.c : col.c + "2E",
                borderColor: (encendida || fallada || modo === "listo") ? "#20120A" : col.c + "77",
                transform: encendida ? "scale(0.94)" : "none",
                boxShadow: encendida ? "0 0 18px " + col.c : "none",
              }}>
              {/* sin el nombre escrito: se memoriza el color, no la palabra */}
            </button>
          );
        })}
      </div>

      {modo === "listo" && (
        <button className="ea-mini" style={{ marginTop: 10 }}
          onClick={() => { setCuenta(0); setModo("ver"); }}>
          Ya lo miré, empezar
        </button>
      )}
      {VIDAS > 1 && (
        <div className="ea-vidas">
          {Array.from({ length: VIDAS }, (_, k) => (
            <span key={k} className={"ea-vida" + (k < vidas ? " viva" : "")} />
          ))}
        </div>
      )}
      <div style={{ minHeight: 22, marginTop: 8, fontSize: 13.5, color: "#6B6B6B" }}>{aviso}</div>
    </div>
  );
}


function JuegoOjo({ ayuda, onFin }) {
  const segs = clamp(3.5 + ayuda / 28, 3.5, 7.5);
  const armar = () => {
    const a = Math.floor(1000 + Math.random() * 8000);
    const s = a.toString();
    const arr = s.split("");
    const i = Math.floor(Math.random() * 3);
    const tmp = arr[i]; arr[i] = arr[i + 1]; arr[i + 1] = tmp;
    let b = arr.join("");
    if (b === s) b = (a + 9).toString();
    const fila = Array.from({ length: 12 }, () => s);
    const pos = Math.floor(Math.random() * 12);
    fila[pos] = b;
    return { fila, pos };
  };
  const [ronda, setRonda] = useState(0);
  const [tab, setTab] = useState(armar);
  const [hits, setHits] = useState(0);
  const [t, setT] = useState(segs);
  const [aviso, setAviso] = useState(null);

  const resolver = (ok) => {
    if (aviso) return;
    const h = hits + (ok ? 1 : 0);
    setHits(h);
    setAviso(ok ? "Correcto" : "Se te pasó");
    setTimeout(() => {
      if (ronda >= 2) onFin(h >= 3 ? "exito" : h === 2 ? "parcial" : "fallo");
      else { setRonda(ronda + 1); setTab(armar()); setT(segs); setAviso(null); }
    }, 750);
  };

  useEffect(() => {
    if (aviso) return;
    const id = setInterval(() => setT((x) => Math.max(0, +(x - 0.1).toFixed(1))), 100);
    return () => clearInterval(id);
  }, [aviso, ronda]);

  useEffect(() => { if (t === 0) resolver(false); }, [t]);

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Cifra {ronda + 1} de 3</span><span>{t.toFixed(1)} s · aciertos {hits}</span></div>
      <div className="ea-nums">
        {tab.fila.map((n, i) => (
          <div className="ea-num ea-mono" key={i} {...pulsable(() => resolver(i === tab.pos), "Cifra " + n)}>{n}</div>
        ))}
      </div>
      <div style={{ minHeight: 22, marginTop: 10, fontSize: 13.5, color: "#6B6B6B" }}>{aviso}</div>
    </div>
  );
}

function JuegoAnclaje({ ayuda, onFin }) {
  const ancho = clamp(8 + ayuda * 0.1, 8, 20);
  const [centro] = useState(() => 18 + Math.random() * 64);
  const [v, setV] = useState(50);
  const [n, setN] = useState(0);
  const [hist, setHist] = useState([]);
  const [cerrado, setCerrado] = useState(false);

  const ofrecer = () => {
    const dif = v - centro;
    const dentro = Math.abs(dif) <= ancho / 2;
    const intento = n + 1;
    let msg;
    if (dentro) msg = "Acuerdo cerrado";
    else if (Math.abs(dif) > 24) msg = dif > 0 ? "Muy por encima de lo que pagan" : "Muy por debajo, dejas valor en la mesa";
    else msg = dif > 0 ? "Un poco alto, están cerca" : "Un poco bajo, están cerca";
    setHist([...hist, { v, msg, dentro }]);
    setN(intento);
    if (dentro) { setCerrado(true); setTimeout(() => onFin(intento <= 2 ? "exito" : "parcial"), 750); }
    else if (intento >= 4) { setCerrado(true); setTimeout(() => onFin("fallo"), 750); }
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Oferta {Math.min(n + 1, 4)} de 4</span><span>Te quedan {Math.max(0, 4 - n)}</span></div>
      <p className="ea-memoTxt" style={{ marginTop: 0 }}>
        Tu número es <strong>lo agresiva que es tu oferta</strong>, de 0 a 100. La otra parte acepta dentro
        de una franja estrecha que no ves. Cada vez que pones un número te dicen si te quedaste corto, si te
        pasaste o si estás cerca, y con eso vas cerrando el cerco.
      </p>
      <div className="ea-anclaN">{v}</div>
      <input className="ea-slider" type="range" min="0" max="100" value={v} disabled={cerrado}
        onChange={(e) => setV(entero(e.target.value, 50, 0, 100))} aria-label="Lo agresiva que es tu oferta" />
      <div className="ea-anclaE ea-dis">
        <span>0 · lo regalas</span>
        <span>100 · te levantan de la mesa</span>
      </div>
      <div style={{ marginTop: 10 }}>
        {hist.map((h, i) => (
          <div key={i} style={{ fontSize: 13.5, color: h.dentro ? "#3D8A49" : "#6B6B6B" }}>
            <span className="ea-mono">{h.v}</span> · {h.msg}
          </div>
        ))}
      </div>
      <button className="ea-btn" onClick={ofrecer} disabled={cerrado}>Poner el número sobre la mesa</button>
    </div>
  );
}

/* ---- Aguantar la posición: el múltiplo sube solo hasta que se da vuelta ----
   Antes era pulsar «aguantar» y tirar un dado cada vez. Ahora el número
   sube poco a poco y el jugador decide cuándo cerrar, sin saber dónde se
   va a dar vuelta: la regla de salida tiene que traerla él.

   Dónde se da vuelta: P(llegar a m) = k / m, la forma clásica. Con k < 1
   a veces se da vuelta nada más abrir, y cuanto más alto, más raro llegar.
   El atributo mueve k: con mejor criterio aguanta un poco más en promedio.
   Tope en 10x para que un intento no dure para siempre.

   Tres intentos y cuenta el MEJOR: reventar uno no te saca del juego, que
   es justo lo que da ganas de volver a intentarlo. Medido con 40.000
   tiradas (k 0,94): salir siempre en 3x da éxito ~68%; salir en 5x, ~46%;
   salir en 2x casi nunca falla pero nunca pasa de parcial. */
const SUERTE_INTENTOS = 3;
const SUERTE_EXITO = 3;
const SUERTE_PARCIAL = 2;
const SUERTE_TOPE = 10;
const SUERTE_PASO = 1.02;      /* por cada tick de 100 ms: 2x en ~3,5 s, 3x en ~5,5 s */
const vueltaSuerte = (ayuda) => {
  const k = clamp(0.8 + numero(ayuda, 0) / 500, 0.8, 0.97);
  const u = clamp(numero(Math.random(), 0.5), 0, 0.999999);
  return clamp(k / (1 - u), 1, SUERTE_TOPE);
};
const fmtX = (m) => m.toFixed(2).replace(".", ",") + "x";

function JuegoSuerte({ ayuda, onFin }) {
  const [intento, setIntento] = useState(0);
  const [mult, setMult] = useState(1);
  const [fase, setFase] = useState("listo");   /* listo · subiendo · cerrado · vuelta · fin */
  const [hist, setHist] = useState([]);        /* { m, ok, vuelta } por intento */
  const vuelta = useRef(1);
  const actual = useRef(1);        /* el múltiplo vivo, sin esperar al render */
  const abierto = useRef(false);   /* un intento solo se cierra una vez */

  const mejor = hist.reduce((a, h) => (h.ok && h.m > a ? h.m : a), 0);
  const quedan = SUERTE_INTENTOS - hist.length;

  /* el número sube solo mientras el intento está abierto */
  useEffect(() => {
    if (fase !== "subiendo") return;
    const t = setInterval(() => {
      if (!abierto.current) return;
      const sig = +(actual.current * SUERTE_PASO).toFixed(4);
      if (sig >= vuelta.current) {
        abierto.current = false;
        actual.current = vuelta.current;
        setMult(vuelta.current);
        setFase("vuelta");
        setHist((h) => h.concat({ m: vuelta.current, ok: false, vuelta: vuelta.current }));
        return;
      }
      actual.current = sig;
      setMult(sig);
    }, 100);
    return () => clearInterval(t);
  }, [fase]);

  /* terminados los tres intentos, se cierra con el mejor */
  useEffect(() => {
    if (hist.length < SUERTE_INTENTOS || fase === "fin") return;
    setFase("fin");
    const nv = mejor >= SUERTE_EXITO ? "exito" : mejor >= SUERTE_PARCIAL ? "parcial" : "fallo";
    const t = setTimeout(() => onFin(nv), 1300);
    return () => clearTimeout(t);
  }, [hist.length]);

  const abrir = () => {
    if (fase !== "listo" && fase !== "cerrado" && fase !== "vuelta") return;
    if (hist.length >= SUERTE_INTENTOS) return;
    vuelta.current = vueltaSuerte(ayuda);
    setIntento(hist.length + 1);
    actual.current = 1;
    setMult(1);
    /* a veces se da vuelta nada más abrir: también pasa en los mercados */
    if (vuelta.current <= 1.0001) {
      setFase("vuelta");
      setHist((h) => h.concat({ m: 1, ok: false, vuelta: 1 }));
      return;
    }
    abierto.current = true;
    setFase("subiendo");
  };
  const cerrar = () => {
    if (fase !== "subiendo" || !abierto.current) return;
    abierto.current = false;
    const m = actual.current;
    setMult(m);
    setFase("cerrado");
    setHist((h) => h.concat({ m, ok: true, vuelta: vuelta.current }));
  };

  const ultimo = hist[hist.length - 1];
  const color = fase === "vuelta" ? "var(--rojo)" : fase === "cerrado" ? "#2F7A3D" : undefined;
  const aviso = fase === "listo" ? "Cuando abras, el múltiplo empieza a subir. Cierra antes de que se dé vuelta."
    : fase === "subiendo" ? "Subiendo… ¿cierras o aguantas?"
    : fase === "cerrado" ? "Cerraste en " + fmtX(ultimo.m) + ". Se iba a dar vuelta en " + fmtX(ultimo.vuelta) + "."
    : fase === "vuelta" ? (ultimo && ultimo.vuelta <= 1.0001 ? "Se dio vuelta nada más abrir. Pasa." : "Se dio vuelta en " + fmtX(ultimo.vuelta) + ". Ese intento se pierde.")
    : mejor >= SUERTE_EXITO ? "Te quedas con " + fmtX(mejor) + ". Éxito."
    : mejor >= SUERTE_PARCIAL ? "Te quedas con " + fmtX(mejor) + ". Resultado a medias."
    : mejor > 0 ? "Te quedas con " + fmtX(mejor) + ". Muy poco para lo que arriesgaste." : "Los tres se dieron vuelta.";

  return (
    <div className="ea-jw ea-jwCentro">
      <div className="ea-jinfo ea-dis">
        <span>{intento ? "Intento " + intento + " de " + SUERTE_INTENTOS : "Tres intentos"}</span>
        <span>Tu mejor {mejor ? fmtX(mejor) : "—"}</span>
      </div>
      <div className="ea-mult ea-mono" style={color ? { color } : undefined}>{fmtX(mult)}</div>
      <div className="ea-suerteMeta ea-mono">éxito desde {fmtX(SUERTE_EXITO)} · a medias desde {fmtX(SUERTE_PARCIAL)}</div>
      <div style={{ minHeight: 22, marginTop: 8, fontSize: 13.5, color: "#6B6B6B" }}>{aviso}</div>
      {fase === "subiendo" ? (
        <button className="ea-btn" style={{ background: "var(--cobre)" }} onClick={cerrar}>Cerrar en {fmtX(mult)}</button>
      ) : fase !== "fin" ? (
        <button className="ea-btn" onClick={abrir}>
          {fase === "listo" ? "Abrir la posición" : "Otro intento · quedan " + quedan}
        </button>
      ) : null}
      {hist.length > 0 && (
        <div className="ea-suerteHist">
          {hist.map((h, i) => (
            <span key={i} className={"ea-suerteH ea-mono" + (h.ok ? " ok" : " mal")}>
              {i + 1} · {h.ok ? "cerraste " + fmtX(h.m) : "vuelta " + fmtX(h.vuelta)}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

const LINEAS = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];

function JuegoTresRaya({ ayuda, onFin }) {
  const [b, setB] = useState(Array(9).fill(null));
  const [bloqueo, setBloqueo] = useState(false);
  const [estado, setEstado] = useState(null);
  const [linea, setLinea] = useState([]);
  const torpeza = clamp(ayuda / 150, 0.08, 0.6);

  const ganador = (bd, p) => LINEAS.find((l) => l.every((i) => bd[i] === p));
  const libres = (bd) => bd.reduce((a, v, i) => (v === null ? a.concat(i) : a), []);

  const jugadaIA = (bd) => {
    const l = libres(bd);
    if (Math.random() < torpeza) return elegirAzar(l);
    for (const i of l) { const t = bd.slice(); t[i] = "O"; if (ganador(t, "O")) return i; }
    for (const i of l) { const t = bd.slice(); t[i] = "X"; if (ganador(t, "X")) return i; }
    if (bd[4] === null) return 4;
    const esq = [0, 2, 6, 8].filter((i) => bd[i] === null);
    if (esq.length) return elegirAzar(esq);
    return l[0];
  };

  const terminar = (n, l) => { setEstado(n); setLinea(l || []); setBloqueo(true); setTimeout(() => onFin(n), 1050); };

  const tocar = (i) => {
    if (bloqueo || b[i] || estado) return;
    const nb = b.slice(); nb[i] = "X"; setB(nb);
    const g = ganador(nb, "X");
    if (g) { terminar("exito", g); return; }
    if (libres(nb).length === 0) { terminar("parcial"); return; }
    setBloqueo(true);
    setTimeout(() => {
      const j = jugadaIA(nb);
      const nb2 = nb.slice(); nb2[j] = "O"; setB(nb2);
      const g2 = ganador(nb2, "O");
      if (g2) { terminar("fallo", g2); return; }
      if (libres(nb2).length === 0) { terminar("parcial"); return; }
      setBloqueo(false);
    }, 400);
  };

  const txt = { exito: "Cerraste en tus términos", parcial: "Empate, partieron la diferencia", fallo: "Te sacaron las concesiones" };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Tú juegas con X</span><span>Lectura de la contraparte {Math.round(100 - torpeza * 100)}</span></div>
      <div className="ea-celdas">
        {b.map((v, i) => (
          <div key={i} className={"ea-celda" + (linea.indexOf(i) >= 0 ? " gana" : "")}
            {...pulsable(() => tocar(i), "Casilla " + (i + 1) + (v ? ", ocupada por " + v : ", libre"), !!v)}>{v}</div>
        ))}
      </div>
      <div style={{ minHeight: 22, marginTop: 12, fontSize: 14, color: "#6B6B6B" }}>{estado ? txt[estado] : ""}</div>
    </div>
  );
}

/* una pregunta solo es utilizable si tiene enunciado, al menos dos
   opciones y un índice de respuesta correcta que apunte a una de ellas */
const preguntaValida = (p) => !!(p && typeof p.q === "string" && p.q &&
  Array.isArray(p.o) && p.o.length >= 2 &&
  Number.isInteger(p.c) && p.c >= 0 && p.c < p.o.length &&
  typeof p.o[p.c] === "string");

const PREGUNTA_RESERVA = {
  q: "Tu cartera cae 30% en un año malo. ¿Qué es lo más sensato?",
  o: ["Mantener el plan y seguir aportando si tu horizonte es largo", "Vender todo y esperar la señal de entrada", "Cambiar a lo que más subió el año pasado", "Duplicar la apuesta con dinero prestado"],
  c: 0,
  e: "Vender en la caída convierte una pérdida temporal en permanente. La caída solo es definitiva para quien vende.",
  nv: 1,
};

function JuegoQuiz({ ayuda, nivel, onFin, modo, temas }) {
  const nv = clamp(numero(nivel, 1), 1, 5);
  const total = largoExamen(nv);
  const [preg] = useState(() => {
    let crudas = [];
    try { crudas = armarExamen(nv, total, temas) || []; } catch (e) { crudas = []; }
    crudas = crudas.filter(preguntaValida);
    while (crudas.length === 0) crudas = [PREGUNTA_RESERVA];
    return crudas.map((p) => {
      const correcta = p.o[p.c];
      let ops = p.o.slice();
      if (ayuda >= 55 && ops.length > 2) {
        const malas = ops.filter((x) => x !== correcta);
        const fuera = elegirAzar(malas);
        if (fuera != null) ops = ops.filter((x) => x !== fuera);
      }
      ops = ops.sort(() => Math.random() - 0.5);
      return { q: p.q, e: texto(p.e, "", 400), ops, correcta, nv: p.nv, tema: p.tema };
    });
  });
  const [i, setI] = useState(0);
  const [sel, setSel] = useState(null);
  const [ok, setOk] = useState(0);
  const [ayudas, setAyudas] = useState(0);
  const [verContexto, setVerContexto] = useState(false);
  const p = preg[Math.min(i, preg.length - 1)] || PREGUNTA_RESERVA;
  const ctx = contextoDe(p);

  const responder = (t) => {
    if (sel !== null) return;
    setSel(t);
    setOk(ok + (t === p.correcta ? 1 : 0));
  };

  const cuantas = preg.length;
  const seguir = () => {
    if (i >= cuantas - 1) {
      /* Con todas bien y sin pedir ayuda, éxito. Pedir explicación no
         se castiga con un fallo, pero sí impide el pleno: aprendiste,
         no acertaste. */
      const pleno = ok === cuantas && ayudas === 0;
      onFin(pleno ? "exito" : ok / cuantas >= 0.6 ? "parcial" : "fallo");
    } else { setI(i + 1); setSel(null); setVerContexto(false); }
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>Pregunta {i + 1} de {cuantas} · {(NIVEL_N[nv] || "").toLowerCase()}</span>
        <span>{"Aciertos " + ok + (ayudas > 0 ? " · " + ayudas + (ayudas === 1 ? " explicación" : " explicaciones") : "")}</span>
      </div>
      {/* El recordatorio era un bloque de cuatro lineas delante de CADA
          pregunta en modo aprendiz. Ahora es una linea con el termino, y
          se abre quien lo necesite: la ayuda sigue estando, pero deja de
          leerse cuatro veces por examen sin que nadie la pidiera. */}
      {ctx && (
        <button className="ea-recuerda ea-dis"
          onClick={() => { if (!verContexto) setAyudas(ayudas + 1); setVerContexto(!verContexto); }}>
          {verContexto ? "↑" : "↓"} Recordatorio · {ctx.t}
        </button>
      )}
      {ctx && verContexto && (
        <div className="ea-glos ea-panelAb">
          <div className="ea-glosX">{ctx.x}</div>
          {ctx.ej && <div className="ea-glosX" style={{ marginTop: 6, fontStyle: "italic" }}>{ctx.ej}</div>}
        </div>
      )}
      <p className="ea-qtxt">{p.q}</p>
      <div className="ea-ops" style={{ marginTop: 0 }}>
        {p.ops.map((t, k) => {
          let cls = "ea-op";
          if (sel !== null && t === p.correcta) cls += " ok";
          else if (sel === t) cls += " no";
          return (
            <button className={cls} key={k} disabled={sel !== null} onClick={() => responder(t)}>
              <span className="ea-opN ea-mono">{String.fromCharCode(65 + k)}</span>{t}
            </button>
          );
        })}
      </div>
      {sel !== null && (
        <div>
          <div className="ea-expl">{p.e}</div>
          <button className="ea-btn" onClick={seguir}>{i >= cuantas - 1 ? "Terminar" : "Continuar"}</button>
        </div>
      )}
    </div>
  );
}

/* ---- rápidos ---- */

function JuegoReaccion({ ayuda, onFin }) {
  const [estado, setEstado] = useState("espera");
  const [ronda, setRonda] = useState(0);
  const [puntos, setPuntos] = useState(0);
  const [msg, setMsg] = useState("Prepárate");
  const t0 = useRef(0);
  const timer = useRef(null);
  const bueno = 380 + ayuda * 2.4;
  const regular = 720 + ayuda * 2.4;

  useEffect(() => {
    setEstado("espera"); setMsg("Prepárate");
    timer.current = setTimeout(() => {
      setEstado("lista"); setMsg("Ahora"); t0.current = Date.now();
    }, 800 + Math.random() * 1900);
    return () => clearTimeout(timer.current);
  }, [ronda]);

  const avanzar = (p, texto) => {
    const total = puntos + p;
    setPuntos(total); setEstado("hecho"); setMsg(texto);
    clearTimeout(timer.current);
    setTimeout(() => {
      if (ronda >= 2) onFin(total >= 5 ? "exito" : total >= 3 ? "parcial" : "fallo");
      else setRonda(ronda + 1);
    }, 850);
  };

  const click = () => {
    if (estado === "espera") { avanzar(0, "Te adelantaste, orden al precio equivocado"); return; }
    if (estado !== "lista") return;
    const ms = Date.now() - t0.current;
    if (ms <= bueno) avanzar(2, ms + " ms, ejecución perfecta");
    else if (ms <= regular) avanzar(1, ms + " ms, pasable");
    else avanzar(0, ms + " ms, se movió el precio");
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Orden {ronda + 1} de 3</span><span>Puntos {puntos} de 6</span></div>
      <div aria-label="Ejecutar la orden"
        className={"ea-luz" + (estado === "lista" ? " lista" : estado === "hecho" ? " roja" : "")}
        onClick={click} role="button" tabIndex={0}
        onKeyDown={(e) => { if (e.key === " " || e.key === "Enter") click(); }}>
        {msg}
      </div>
      <div style={{ fontSize: 12.5, color: "var(--gris)", marginTop: 9 }}>Toca el panel apenas se ponga verde.</div>
    </div>
  );
}

/* cada generador declara desde qué nivel aparece, así las cuentas
   se van complicando en vez de repetirse durante treinta años */
const CUENTAS = [
  { min: 1, f: () => {
    const v = [80, 100, 120, 150, 200][Math.floor(Math.random() * 5)];
    const mrg = [10, 15, 20, 25][Math.floor(Math.random() * 4)];
    const u = v * mrg / 100;
    return { q: `Ventas de ${v} y utilidad de ${u}. El margen es`, ops: [mrg, mrg + 5, Math.round(u / (v + u) * 100)], c: mrg, u: "%" };
  } },
  { min: 1, f: () => {
    const compra = [40, 50, 80, 120][Math.floor(Math.random() * 4)];
    const f = [1.25, 1.5, 1.75, 2][Math.floor(Math.random() * 4)];
    const c = Math.round((f - 1) * 100);
    return { q: `Compraste a ${compra} y vendiste a ${compra * f}. Tu retorno es`, ops: [c, Math.round((1 - 1 / f) * 100), c + 10], c, u: "%" };
  } },
  { min: 1, f: () => {
    const r = [4, 6, 8, 9, 12][Math.floor(Math.random() * 5)];
    const c = Math.round(72 / r);
    return { q: `A una tasa de ${r}% anual, el capital se duplica aproximadamente en`, ops: [c, c + 4, Math.max(2, c - 3)], c, u: " años" };
  } },
  { min: 2, f: () => {
    const eb = 8 + Math.floor(Math.random() * 12), m = 4 + Math.floor(Math.random() * 5), dn = 10 + Math.floor(Math.random() * 25);
    const c = eb * m - dn;
    return { q: `EBITDA de ${eb} millones, múltiplo de ${m} veces y deuda neta de ${dn} millones. El equity value es`, ops: [c, eb * m + dn, eb * (m - 1) - dn], c, u: " millones" };
  } },
  { min: 2, f: () => {
    const dur = [3, 4, 5, 6, 8][Math.floor(Math.random() * 5)];
    const pb = [1, 2][Math.floor(Math.random() * 2)];
    const c = dur * pb;
    return { q: `Duración modificada de ${dur} y las tasas suben ${pb}%. El precio del bono cae cerca de`, ops: [c, pb, dur], c, u: "%" };
  } },
  { min: 2, f: () => {
    const renta = [60, 90, 120, 180][Math.floor(Math.random() * 4)];
    const cap = [6, 8, 9, 10][Math.floor(Math.random() * 4)];
    const c = Math.round(renta / (cap / 100));
    return { q: `Un inmueble renta ${renta} mil netos al año y el mercado paga una tasa de capitalización de ${cap}%. Vale cerca de`, ops: [c, Math.round(renta * cap), Math.round(renta / (cap / 50))], c, u: " mil" };
  } },
  { min: 3, f: () => {
    const eb = [20, 30, 40, 60][Math.floor(Math.random() * 4)];
    const d = [80, 120, 150, 200][Math.floor(Math.random() * 4)];
    const tasa = [8, 10, 12][Math.floor(Math.random() * 3)];
    const int = d * tasa / 100;
    const c = +(eb / int).toFixed(1);
    return { q: `EBITDA de ${eb} y deuda de ${d} al ${tasa}%. La cobertura de intereses es`, ops: [c, +(eb / d * 10).toFixed(1), +(int / eb).toFixed(1)], c, u: " veces" };
  } },
  { min: 3, f: () => {
    const acc = [80, 100, 120][Math.floor(Math.random() * 3)];
    const nue = [20, 25, 40][Math.floor(Math.random() * 3)];
    const c = Math.round(nue / (acc + nue) * 100);
    return { q: `Hay ${acc} millones de acciones y se emiten ${nue} millones nuevas. La dilución del accionista actual es`, ops: [c, Math.round(nue / acc * 100), Math.round(acc / nue)], c, u: "%" };
  } },
  { min: 3, f: () => {
    const ebit = [50, 70, 90][Math.floor(Math.random() * 3)];
    const tax = [25, 30, 34][Math.floor(Math.random() * 3)];
    const dep = [10, 15, 20][Math.floor(Math.random() * 3)];
    const capex = [15, 25, 30][Math.floor(Math.random() * 3)];
    const c = Math.round(ebit * (1 - tax / 100) + dep - capex);
    return { q: `EBIT de ${ebit}, impuesto ${tax}%, depreciación ${dep} y capex ${capex}, sin cambio en capital de trabajo. El flujo libre a la firma es`, ops: [c, Math.round(ebit + dep - capex), Math.round(ebit * (1 - tax / 100) - dep + capex)], c, u: "" };
  } },
  { min: 4, f: () => {
    const we = [40, 50, 60][Math.floor(Math.random() * 3)];
    const ke = [14, 16, 18][Math.floor(Math.random() * 3)];
    const kd = [8, 9, 10][Math.floor(Math.random() * 3)];
    const tax = 30;
    const c = +((we / 100) * ke + (1 - we / 100) * kd * (1 - tax / 100)).toFixed(1);
    return { q: `Capital propio ${we}% al ${ke}, deuda al ${kd} con impuesto de 30. El WACC es`, ops: [c, +((we / 100) * ke + (1 - we / 100) * kd).toFixed(1), +(((ke + kd) / 2)).toFixed(1)], c, u: "%" };
  } },
  { min: 4, f: () => {
    const eq = [30, 40, 50][Math.floor(Math.random() * 3)];
    const m = [2, 2.5, 3][Math.floor(Math.random() * 3)];
    const anos = [4, 5][Math.floor(Math.random() * 2)];
    const c = Math.round((Math.pow(m, 1 / anos) - 1) * 100);
    return { q: `Pusiste ${eq} de capital y sales en ${Math.round(eq * m)} a los ${anos} años. Tu TIR anual es cerca de`, ops: [c, Math.round((m - 1) * 100), Math.round((m - 1) * 100 / anos)], c, u: "%" };
  } },
  { min: 4, f: () => {
    const cf = [1000, 1500, 2000][Math.floor(Math.random() * 3)];
    const g = [2, 3][Math.floor(Math.random() * 2)];
    const wacc = [9, 10, 12][Math.floor(Math.random() * 3)];
    const c = Math.round(cf * (1 + g / 100) / ((wacc - g) / 100));
    return { q: `Flujo de ${cf} que crece al ${g}% a perpetuidad y se descuenta al ${wacc}. El valor terminal es`, ops: [c, Math.round(cf / (wacc / 100)), Math.round(cf * (1 + g / 100) / (wacc / 100))], c, u: "" };
  } },
  { min: 5, f: () => {
    const local = [24, 30, 36][Math.floor(Math.random() * 3)];
    const usd = [4, 5, 6][Math.floor(Math.random() * 3)];
    const c = local - usd;
    return { q: `Tasa local ${local}% y tasa en dólares ${usd}. Cubrir el riesgo cambiario a un año te cuesta cerca de`, ops: [c, local + usd, Math.round(local / usd)], c, u: "%" };
  } },
  { min: 5, f: () => {
    const pat = [1, 2, 3][Math.floor(Math.random() * 3)];
    const caida = [30, 40, 50][Math.floor(Math.random() * 3)];
    const c = Math.round((1 / (1 - caida / 100) - 1) * 100);
    return { q: `Tu cartera cae ${caida}%. Para volver al punto de partida necesitas subir`, ops: [c, caida, caida + 10], c, u: "%" };
  } },
];

const genCalculo = (nv) => {
  const n = nv || 1;
  let pool = CUENTAS.filter((x) => x.min <= n);
  const duras = pool.filter((x) => x.min >= n - 1);
  if (duras.length && Math.random() < 0.7) pool = duras;
  return elegirAzar(pool).f();
};

function JuegoCalculo({ ayuda, nivel, onFin }) {
  const nv = nivel || 1;
  const segs = clamp(9 + ayuda / 12 - (nv - 1) * 0.7, 6.5, 17);
  const [ronda, setRonda] = useState(0);
  const [p, setP] = useState(() => genCalculo(nv));
  const [sel, setSel] = useState(null);
  const [ok, setOk] = useState(0);
  const [t, setT] = useState(segs);
  const mezcla = useMemo(() => p.ops.slice().sort(() => Math.random() - 0.5), [p]);

  const resolver = (v) => {
    if (sel !== null) return;
    setSel(v === null ? -1 : v);
    const n = ok + (v === p.c ? 1 : 0);
    setOk(n);
  };

  const seguir = () => {
    if (ronda >= 2) onFin(ok >= 3 ? "exito" : ok === 2 ? "parcial" : "fallo");
    else { setRonda(ronda + 1); setP(genCalculo(nv)); setSel(null); setT(segs); }
  };

  useEffect(() => {
    if (sel !== null) return;
    const id = setInterval(() => setT((x) => Math.max(0, +(x - 0.1).toFixed(1))), 100);
    return () => clearInterval(id);
  }, [sel, ronda]);

  useEffect(() => { if (t === 0 && sel === null) resolver(null); }, [t]);

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Cuenta {ronda + 1} de 3</span><span>{t.toFixed(1)} s · aciertos {ok}</span></div>
      <p className="ea-qtxt">{p.q}</p>
      <div className="ea-ops" style={{ marginTop: 0 }}>
        {mezcla.map((v, k) => {
          let cls = "ea-op";
          if (sel !== null && v === p.c) cls += " ok";
          else if (sel === v) cls += " no";
          return (
            <button className={cls} key={k} disabled={sel !== null} onClick={() => resolver(v)}>
              <span className="ea-opN ea-mono">{String.fromCharCode(65 + k)}</span>
              <span className="ea-mono">{v}{p.u}</span>
            </button>
          );
        })}
      </div>
      {sel !== null && (
        <div>
          <div className="ea-expl">{sel === p.c ? "Correcto. " : "La respuesta era " + p.c + p.u + ". "}Sin calculadora y contra reloj, este tipo de cuenta se hace todos los días en una mesa.</div>
          <button className="ea-btn" onClick={seguir}>{ronda >= 2 ? "Terminar" : "Continuar"}</button>
        </div>
      )}
    </div>
  );
}

/* ---- Poner en orden ----
   Reescrito: antes un solo error terminaba el juego. Ahora tienes tres
   intentos, el error se marca en rojo un momento y puedes seguir desde
   donde ibas. Además se dice explícitamente qué criterio se está
   ordenando y se numeran los que ya colocaste. */

const VIDAS_ORDEN = 3;

function JuegoOrden({ ayuda, onFin }) {
  const [set] = useState(() => elegirAzar(ORDENES) || ORDENES[0]);
  const [lista] = useState(() => set.l.slice().sort(() => Math.random() - 0.5));
  const [paso, setPaso] = useState(() => (ayuda >= 60 ? 1 : 0));
  const [err, setErr] = useState(null);
  const [vidas, setVidas] = useState(VIDAS_ORDEN);
  const [fin, setFin] = useState(false);
  const [aviso, setAviso] = useState(null);

  const total = set.l.length;

  const tocar = (item) => {
    if (fin || err) return;
    if (item === set.l[paso]) {
      const p = paso + 1;
      setPaso(p);
      setAviso(null);
      if (p >= total) {
        setFin(true);
        setAviso("Secuencia correcta");
        setTimeout(() => onFin(vidas === VIDAS_ORDEN ? "exito" : vidas === VIDAS_ORDEN - 1 ? "parcial" : "parcial"), 700);
      }
      return;
    }
    const quedan = vidas - 1;
    setErr(item);
    setVidas(quedan);
    if (quedan <= 0) {
      setFin(true);
      setAviso("Se acabaron los intentos");
      setTimeout(() => onFin(paso >= Math.ceil(total / 2) ? "parcial" : "fallo"), 800);
      return;
    }
    setAviso("Ese no va aquí. Te quedan " + quedan + (quedan === 1 ? " intento." : " intentos."));
    setTimeout(() => setErr(null), 700);
  };

  const puesto = (item) => set.l.indexOf(item) < paso;

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>Colocados {paso} de {total}</span>
        <span>Intentos {vidas} de {VIDAS_ORDEN}</span>
      </div>
      <Pista>
        Toca los elementos en el orden que pide el enunciado, del primero al último.
        Equivocarte cuesta un intento, no la partida.
      </Pista>
      <p className="ea-qtxt">{set.t}</p>
      <div className="ea-ordenL">
        {lista.map((item, k) => (
          <button key={k} disabled={puesto(item) || fin}
            className={"ea-ordenI" + (puesto(item) ? " hecho" : "") + (err === item ? " err" : "")}
            onClick={() => tocar(item)}>
            <span>{item}</span>
            <span className="ea-ordenN ea-mono">{puesto(item) ? set.l.indexOf(item) + 1 : ""}</span>
          </button>
        ))}
      </div>
      <div className="ea-vidas">
        {Array.from({ length: VIDAS_ORDEN }, (_, k) => (
          <span key={k} className={"ea-vida" + (k < vidas ? " viva" : "")} />
        ))}
      </div>
      <div style={{ minHeight: 22, marginTop: 8, fontSize: 13.5, color: "#6B6B6B" }}>{aviso}</div>
    </div>
  );
}

function JuegoSemaforo({ ayuda, nivel, onFin }) {
  const segs = clamp(2.4 + ayuda / 90 - ((nivel || 1) - 1) * 0.18, 1.5, 3.5);
  const [serie] = useState(() => SENALES.slice().sort(() => Math.random() - 0.5).slice(0, 6));
  const [i, setI] = useState(0);
  const [ok, setOk] = useState(0);
  const [marca, setMarca] = useState(null);
  const [t, setT] = useState(segs);

  const responder = (a) => {
    if (marca !== null) return;
    const acierto = a === serie[i].a;
    setMarca(acierto ? "bien" : "mal");
    const n = ok + (acierto ? 1 : 0);
    setOk(n);
  };

  const seguir = () => {
    if (i >= 5) onFin(ok >= 5 ? "exito" : ok >= 4 ? "parcial" : "fallo");
    else { setI(i + 1); setMarca(null); setT(segs); }
  };

  useEffect(() => {
    if (marca !== null) return;
    const id = setInterval(() => setT((x) => Math.max(0, +(x - 0.1).toFixed(1))), 100);
    return () => clearInterval(id);
  }, [marca, i]);

  useEffect(() => { if (t === 0 && marca === null) responder("nada"); }, [t]);

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Señal {i + 1} de 6</span><span>{t.toFixed(1)} s · aciertos {ok}</span></div>
      <div className={"ea-luz" + (marca === "bien" ? " lista" : marca === "mal" ? " roja" : "")}>{serie[i].t}</div>
      <div className="ea-fila2">
        <button className="ea-btn" style={{ marginTop: 0, flex: 1 }} onClick={() => responder("comprar")} disabled={marca !== null}>Comprar</button>
        <button className="ea-btn" style={{ marginTop: 0, flex: 1, background: "var(--rojo)" }} onClick={() => responder("vender")} disabled={marca !== null}>Vender</button>
      </div>
      {marca !== null && (
        <div>
          <div className="ea-expl">{marca === "bien" ? "Bien leído. " : "Era para " + serie[i].a + ". "}En la mesa se decide con esta información y en este tiempo.</div>
          <button className="ea-btn" onClick={seguir}>{i >= 5 ? "Terminar" : "Continuar"}</button>
        </div>
      )}
    </div>
  );
}

function MiniJuego({ tipo, ayuda, nivel, onFin, modo, temas, onTema }) {
  if (tipo === "precision") return <JuegoPrecision ayuda={ayuda} onFin={onFin} />;
  if (tipo === "memoria") return <JuegoMemoria ayuda={ayuda} onFin={onFin} />;
  if (tipo === "ojo") return <JuegoOjo ayuda={ayuda} onFin={onFin} />;
  if (tipo === "anclaje") return <JuegoAnclaje ayuda={ayuda} onFin={onFin} />;
  if (tipo === "tresraya") return <JuegoTresRaya ayuda={ayuda} onFin={onFin} />;
  if (tipo === "quiz") return <JuegoQuiz ayuda={ayuda} nivel={nivel} onFin={onFin} modo={modo} temas={temas} />;
  if (tipo === "catedra") return <JuegoCatedra ayuda={ayuda} nivel={nivel} onFin={onFin} onTema={onTema} />;
  if (tipo === "comite") return <JuegoComite ayuda={ayuda} onFin={onFin} />;
  if (tipo === "reaccion") return <JuegoReaccion ayuda={ayuda} onFin={onFin} />;
  if (tipo === "calculo") return <JuegoCalculo ayuda={ayuda} nivel={nivel} onFin={onFin} />;
  if (tipo === "orden") return <JuegoOrden ayuda={ayuda} onFin={onFin} />;
  if (tipo === "semaforo") return <JuegoSemaforo ayuda={ayuda} nivel={nivel} onFin={onFin} />;
  if (tipo === "trading") return <JuegoTrading ayuda={ayuda} onFin={onFin} />;
  if (tipo === "estructura") return <JuegoEstructura ayuda={ayuda} onFin={onFin} />;
  if (tipo === "banderas") return <JuegoBanderas ayuda={ayuda} onFin={onFin} modo={modo} />;
  if (tipo === "pares") return <JuegoPares ayuda={ayuda} onFin={onFin} />;
  if (tipo === "carril") return <JuegoCarril ayuda={ayuda} onFin={onFin} />;
  if (tipo === "cuatro") return <JuegoCuatro ayuda={ayuda} onFin={onFin} />;
  if (tipo === "subasta") return <JuegoSubasta ayuda={ayuda} onFin={onFin} />;
  return <JuegoSuerte ayuda={ayuda} onFin={onFin} />;
}

/* ---- explicación antes de jugar ----
   Nadie aprende de un juego que no entendió. Primero las reglas,
   qué cuenta como éxito y para qué sirve en la vida real. */
function TarjetaJuego({ tipo, ayuda, nivel, statN, onFin, modo, temas, onTema, visto, onVisto }) {
  /* Tres pasos, no uno. Antes el minijuego aparecia dentro del
     memorando, con la ficha y las pestañas alrededor, y no se notaba
     que cambiabas de actividad. Ahora: el anuncio —una pantalla de
     color que dice HORA DE JUGAR—, las instrucciones grandes sobre
     fondo oscuro, y el juego a pantalla entera sin nada mas. */
  const [paso, setPaso] = useState("anuncio");
  const [listo, setListo] = useState(false);
  /* las reglas, para quien ya jugó esto antes y quiere repasarlas */
  const [recordar, setRecordar] = useState(false);
  /* y el «para qué sirve», que no hace falta antes de jugar */
  const [porQue, setPorQue] = useState(false);

  /* el anuncio se pasa solo, y tambien al toque: quien ya lo vio veinte
     veces no tiene por que esperar */
  useEffect(() => {
    if (paso !== "anuncio") return;
    if (typeof setTimeout !== "function") { setPaso("reglas"); return; }
    const espera = sinMovimiento() ? 60 : 1150;
    const t = setTimeout(() => setPaso("reglas"), espera);
    return () => { try { clearTimeout(t); } catch (e) {} };
  }, [paso]);
  /* El torniquete. Todos los minijuegos cierran por aqui y aqui solo se
     pasa una vez: da igual si el jugador machaca el boton, si un
     setTimeout viejo dispara tarde o si el componente ya se desmonto.
     Un resultado por escena, ni uno mas. */
  const gastado = useRef(false);
  useEffect(() => () => { gastado.current = true; }, []);
  const cerrarUnaVez = (nivelBruto) => {
    if (gastado.current) return;
    gastado.current = true;
    const nv = nivelBruto === "exito" || nivelBruto === "parcial" || nivelBruto === "fallo" ? nivelBruto : "fallo";
    try { onFin(nv); } catch (e) { try { console.error("[El Analista] fin de juego", e); } catch (_) {} }
  };
  const j = JUEGOS[tipo];
  if (!j) return <MiniJuego tipo={tipo} ayuda={ayuda} nivel={nivel} onFin={cerrarUnaVez} modo={modo} temas={temas} onTema={onTema} />;
  if (listo) {
    return (
      <div className="ea-juegoPleno">
        <MiniJuego tipo={tipo} ayuda={ayuda} nivel={nivel} onFin={cerrarUnaVez} modo={modo} temas={temas} onTema={onTema} />
      </div>
    );
  }
  const nivelJuego = tipo === "quiz" || tipo === "calculo" || tipo === "semaforo" || tipo === "catedra";
  const empezar = () => { if (onVisto) onVisto(tipo); setListo(true); };

  /* ---- paso uno: el anuncio ----
     Una pantalla de color que no pide leer nada. Solo avisa de que esto
     ya no es una decision, es otra cosa. */
  if (paso === "anuncio") {
    return (
      <div className="ea-anuncioJuego" onClick={() => setPaso("reglas")}>
        <div className="ea-anuncioJK ea-dis">Hora de jugar</div>
        <div className="ea-anuncioJN ea-dis">{j.n}</div>
        <div className="ea-anuncioJT ea-dis">{j.tema} · {j.dur}</div>
      </div>
    );
  }

  /* ---- paso dos: las instrucciones, grandes y encima ----
     Sobre un fondo oscurecido para que no compitan con nada. Quien ya
     jugo esto se salta los pasos: le basta el nombre y el boton. */
  return (
    <div className="ea-reglasPleno">
      <div className="ea-reglasCaja">
        <div className="ea-jnombre ea-dis"><span>{visto ? "Otra vez" : "Vas a jugar"}</span>{j.n}</div>
        <div className="ea-jmeta">
          {!visto && <span className="ea-jtag">{j.tema}</span>}
          <span className="ea-jtag">{j.dur}</span>
          {nivelJuego && <span className="ea-jtag">Nivel {nivel} · {NIVEL_N[nivel]}</span>}
          <span className="ea-jtag">{statN} {Math.round(ayuda)}</span>
        </div>

        {!visto && (
          <div>
            <p className="ea-reglasX">{j.i}</p>
            <ul className="ea-pasos ea-pasosG">
              {j.pasos.map((t, i) => (
                <li className="ea-paso" key={i}><span className="ea-pasoN">{i + 1}</span><span>{t}</span></li>
              ))}
            </ul>
            <div className="ea-reglasGana">{j.gana}</div>
          </div>
        )}

        <button className="ea-btn ea-btnJugar" onClick={empezar}>
          {visto ? "Empezar" : "Entendido, empezar"}
        </button>

        {visto && (
          <div>
            <button className="ea-atras ea-dis" style={{ marginTop: 12, marginBottom: 0 }}
              onClick={() => setRecordar((v) => !v)}>
              {recordar ? "↑ Ya me acuerdo" : "↓ Recordarme las reglas"}
            </button>
            {recordar && (
              <div className="ea-panelAb">
                <p className="ea-reglasX">{j.i}</p>
                <ul className="ea-pasos ea-pasosG">
                  {j.pasos.map((t, i) => (
                    <li className="ea-paso" key={i}><span className="ea-pasoN">{i + 1}</span><span>{t}</span></li>
                  ))}
                </ul>
                <div className="ea-reglasGana">{j.gana}</div>
              </div>
            )}
          </div>
        )}

        {!visto && (
          <div>
            <button className="ea-atras ea-dis" style={{ marginTop: 14, marginBottom: 0 }}
              onClick={() => setPorQue((v) => !v)}>
              {porQue ? "↑ Cerrar" : "↓ Para qué sirve esto"}
            </button>
            {porQue && (
              <div className="ea-panelAb">
                <div className="ea-lec" style={{ marginTop: 8 }}>
                  <div className="ea-lecX">{j.ensena}</div>
                </div>
                {modo === "aprendiz" && (GLOS_JUEGO[tipo] || []).map((k) => GLOSARIO[k]).filter(Boolean).map((g, i) => (
                  <div className="ea-glos" key={i}>
                    {i === 0 && <div className="ea-glosK">Palabras que vas a ver</div>}
                    <div className="ea-glosT">{g.n}</div>
                    <div className="ea-glosX">{g.x}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* ---- juegos interactivos nuevos ---- */

/* ---- La clase de las siete ----
   El minijuego que faltaba: te explica un tema, con ejemplo numérico, y
   acto seguido te pregunta por él. Nada de examinar sobre cosas que el
   juego nunca se molestó en enseñar. El tema sale del nivel que te toca,
   y si ya viste todos los de tu nivel, sube o baja uno. */
function JuegoCatedra({ ayuda, nivel, onFin, onTema }) {
  const nv = clamp(numero(nivel, 1), 1, 5);
  const [tema] = useState(() => {
    const enNivel = TEMAS.filter((x) => x.nv === nv);
    const cerca = TEMAS.filter((x) => Math.abs(x.nv - nv) <= 1);
    return elegirAzar(enNivel.length ? enNivel : cerca.length ? cerca : TEMAS) || TEMAS[0];
  });
  const [preg] = useState(() => {
    const buenas = (tema.q || []).filter((p) => p && p.q && Array.isArray(p.ops) && p.ops.indexOf(p.correcta) >= 0);
    const cuantas = ayuda >= 60 ? 2 : Math.min(3, buenas.length);
    return buenas.slice().sort(() => Math.random() - 0.5).slice(0, Math.max(1, cuantas))
      .map((p) => ({ ...p, ops: p.ops.slice().sort(() => Math.random() - 0.5) }));
  });
  const [fase, setFase] = useState("clase");
  const [i, setI] = useState(0);
  const [sel, setSel] = useState(null);
  const [ok, setOk] = useState(0);

  /* Desde que se da la clase, este tema ya puede salir en un examen. */
  const avisaTema = useRef(onTema);
  avisaTema.current = onTema;
  useEffect(() => {
    if (avisaTema.current && tema && tema.id) avisaTema.current(tema.id);
  }, []);

  if (fase === "clase") {
    return (
      <div className="ea-jw">
        <div className="ea-jinfo ea-dis">
          <span>Clase · nivel {nv}</span>
          <span>{preg.length} {preg.length === 1 ? "pregunta" : "preguntas"} después</span>
        </div>
        <h3 className="ea-claseT ea-dis">{tema.n}</h3>
        <p className="ea-memoTxt">{tema.x}</p>
        <div className="ea-ej">
          <div className="ea-lecK">Con números</div>
          <div className="ea-ejX">{tema.ej}</div>
        </div>
        <Pista>
          Léelo con calma. Cuando pases de aquí ya no vuelves a ver la explicación.
        </Pista>
        <button className="ea-btn" onClick={() => setFase("quiz")}>Ya lo tengo, pregúntame</button>
      </div>
    );
  }

  const p = preg[Math.min(i, preg.length - 1)];
  const responder = (txt) => {
    if (sel !== null) return;
    setSel(txt);
    if (txt === p.correcta) setOk(ok + 1);
  };
  const seguir = () => {
    if (i >= preg.length - 1) {
      const r = ok / preg.length;
      onFin(r >= 0.999 ? "exito" : r >= 0.5 ? "parcial" : "fallo");
    } else { setI(i + 1); setSel(null); }
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>{tema.n}</span>
        <span>Pregunta {i + 1} de {preg.length} · aciertos {ok}</span>
      </div>
      <p className="ea-qtxt">{p.q}</p>
      <div className="ea-ops" style={{ marginTop: 0 }}>
        {p.ops.map((txt, k) => {
          let cls = "ea-op";
          if (sel !== null && txt === p.correcta) cls += " ok";
          else if (sel === txt) cls += " no";
          return (
            <button className={cls} key={k} disabled={sel !== null} onClick={() => responder(txt)}>
              <span className="ea-opN ea-mono">{String.fromCharCode(65 + (k % 26))}</span>{txt}
            </button>
          );
        })}
      </div>
      {sel !== null && (
        <div>
          <div className="ea-expl">{p.e}</div>
          <button className="ea-btn" onClick={seguir}>{i >= preg.length - 1 ? "Terminar la clase" : "Siguiente"}</button>
        </div>
      )}
    </div>
  );
}

/* ---- La sesión ----
   Reescrito para que se entienda qué estás mirando. Antes decía "Dentro"
   y "Fuera" sin explicar de qué, y comparaba contra un rival invisible.
   Ahora: un cartel grande dice si tienes la acción o estás en efectivo,
   hay leyenda bajo el gráfico, y el rival contra el que compites está
   nombrado desde el primer segundo. */
function JuegoTrading({ ayuda, onFin }) {
  const TICKS = 24;
  const RITMO = 780;
  const [serie] = useState(() => {
    const vol = clamp(0.055 - ayuda * 0.00012, 0.03, 0.055);
    const tendencia = (numero(Math.random(), 0.5) - 0.42) * 0.012;
    const arr = [100];
    for (let i = 1; i < TICKS; i++) {
      arr.push(Math.max(20, arr[i - 1] * (1 + tendencia + vol * gauss())));
    }
    return arr;
  });
  const [i, setI] = useState(0);
  const [dentro, setDentro] = useState(false);
  const [equity, setEquity] = useState(100);
  const [hist, setHist] = useState([100]);
  const [fin, setFin] = useState(false);
  const [ops, setOps] = useState(0);
  const dentroRef = useRef(false);
  useEffect(() => { dentroRef.current = dentro; }, [dentro]);

  useEffect(() => {
    if (fin) return;
    const id = setTimeout(() => {
      if (i >= TICKS - 1) { setFin(true); return; }
      const r = serie[i + 1] / serie[i] - 1;
      const nuevo = dentroRef.current ? equity * (1 + r) : equity;
      setEquity(nuevo);
      setHist((h) => h.concat(nuevo));
      setI(i + 1);
    }, RITMO);
    return () => clearTimeout(id);
  }, [i, fin, serie, equity]);

  const precio = serie[Math.min(i, TICKS - 1)];
  const bench = (precio / serie[0]) * 100;
  const mio = (equity / 100 - 1) * 100;
  const suyo = (bench / 100 - 1) * 100;
  const dif = mio - suyo;

  const path = (datos, alto, max, min) => datos.map((v, k) => {
    const x = (k / (TICKS - 1)) * 100;
    const y = alto - ((v - min) / (max - min || 1)) * alto;
    return (k === 0 ? "M" : "L") + x.toFixed(2) + " " + y.toFixed(2);
  }).join(" ");

  const vistos = serie.slice(0, i + 1);
  const todos = vistos.concat(hist);
  const max = Math.max.apply(null, todos), min = Math.min.apply(null, todos);

  return (
    <div className="ea-jw">
      <Pista>
        Una acción va a moverse durante {TICKS} momentos. Con <strong>Comprar</strong> la tienes y su subida o bajada
        te toca entera; con <strong>Vender</strong> te sales a efectivo y dejas de moverte. Compites contra alguien
        que compró al principio y no volvió a tocar nada. Ganas si terminas por encima de él.
      </Pista>

      <div className={"ea-estado " + (dentro ? "dentro" : "fuera")}>
        {dentro ? "TIENES LA ACCIÓN" : "ESTÁS EN EFECTIVO"}
      </div>

      <div className="ea-jinfo ea-dis" style={{ marginTop: 10 }}>
        <span>Momento {i + 1} de {TICKS}</span>
        <span>Precio {precio.toFixed(1)} · operaciones {ops}</span>
      </div>

      <svg className="ea-graf" viewBox="0 0 100 60" preserveAspectRatio="none">
        <path className="ea-grafL" d={path(vistos, 60, max, min)} vectorEffect="non-scaling-stroke" />
        <path className="ea-grafD" d={path(hist, 60, max, min)} vectorEffect="non-scaling-stroke" />
      </svg>
      <div className="ea-leyenda">
        <span><i className="ea-lineaL" /> precio de la acción</span>
        <span><i className="ea-lineaD" /> tu cuenta</span>
      </div>

      <div className="ea-marcador">
        <div>
          <div className="ea-lecK">Tu cuenta</div>
          <div className="ea-mono ea-marcaV" style={{ color: mio >= 0 ? "#3D8A49" : "var(--rojo)" }}>
            {mio >= 0 ? "+" : ""}{mio.toFixed(1)}%
          </div>
        </div>
        <div>
          <div className="ea-lecK">El que compró y no tocó nada</div>
          <div className="ea-mono ea-marcaV" style={{ color: suyo >= 0 ? "#3D8A49" : "var(--rojo)" }}>
            {suyo >= 0 ? "+" : ""}{suyo.toFixed(1)}%
          </div>
        </div>
        <div>
          <div className="ea-lecK">Le llevas</div>
          <div className="ea-mono ea-marcaV" style={{ color: dif >= 0 ? "#3D8A49" : "var(--rojo)" }}>
            {dif >= 0 ? "+" : ""}{dif.toFixed(1)}
          </div>
        </div>
      </div>

      {!fin ? (
        <div className="ea-fila2">
          <button className="ea-btn" style={{ marginTop: 0, flex: 1 }}
            onClick={() => { setDentro(true); setOps(ops + 1); }} disabled={dentro}>Comprar</button>
          <button className="ea-btn" style={{ marginTop: 0, flex: 1, background: "var(--rojo)" }}
            onClick={() => { setDentro(false); setOps(ops + 1); }} disabled={!dentro}>Vender</button>
        </div>
      ) : (
        <div>
          <div className={"ea-alerta " + (dif >= 4 ? "bien" : dif >= -0.5 ? "" : "mal")}>
            Cerró la sesión. Terminaste {dif >= 0 ? "por encima" : "por debajo"} del que compró al principio
            y se fue a dormir, por {Math.abs(dif).toFixed(1)} puntos, después de {ops} {ops === 1 ? "operación" : "operaciones"}.
            {dif < 0 ? " Es el resultado más común: entrar y salir suele costar más de lo que salva." : " Que salga bien una vez no significa que se pueda repetir treinta años seguidos."}
          </div>
          <button className="ea-btn" onClick={() => onFin(dif >= 4 ? "exito" : dif >= -0.5 ? "parcial" : "fallo")}>Continuar</button>
        </div>
      )}
    </div>
  );
}

/* ---- Armar la estructura ----
   Rehecho otra vez (28-sep-2026). La versión anterior no se podía ganar:
   pedía multiplicar el capital por 2,4 si iba bien, y en todas las empresas
   posibles la cobertura de intereses rompía antes de llegar ahí. Además
   hablaba de EBITDA, cobertura y covenant, y la meta no se veía.

   Ahora: una empresa de 100 millones, una barra (cuánto te presta el
   banco) y dos metas que tiran en sentidos contrarios, con su ✓ en vivo.
     · si le va bien, multiplicar tu dinero por 2 o más  → pide deuda
     · si le va mal, conservar al menos el 30%           → pide poca deuda
   Entre las dos hay una franja buena que se mueve de partida en partida:
   se sortea primero la franja y de ella salen cuánto sube y cuánto baja la
   empresa, así que siempre existe y nunca está en el mismo sitio. Con
   mejor atributo la franja es más ancha. */
const EST_PRECIO = 100;
const EST_META_BIEN = 2;      /* multiplicar tu dinero por esto si va bien */
const EST_META_MAL = 0.3;     /* conservar al menos esta parte si va mal */
const EST_AMORTIZA = 10;      /* lo que la empresa devuelve de deuda si va bien */
const EST_TOPE = 80;          /* ningún banco presta más del 80% */
const casoEstructura = (ayuda) => {
  const lo = 30 + 5 * indiceAzar(5);                       /* de 30 a 50 */
  const ancho = numero(ayuda, 0) >= 60 ? 15 : 10;
  const hi = Math.min(EST_TOPE - 10, lo + ancho);
  /* bien: (100·(1+sube) − (d − 10)) / (100 − d) = 2    justo en d = lo */
  const sube = (EST_PRECIO * EST_META_BIEN - EST_META_BIEN * lo + lo - EST_AMORTIZA) / EST_PRECIO - 1;
  /* mal:  (100·(1−baja) − d) / (100 − d) = 0,3          justo en d = hi */
  const baja = 1 - (EST_META_MAL * (EST_PRECIO - hi) + hi) / EST_PRECIO;
  return { lo, hi, sube, baja,
    nombre: elegirAzar(["Envases del Sur", "Clínica Aurora", "Transportes Bolívar", "Alimentos Real", "Química Andina"]) || "la compañía" };
};
const resultadoEstructura = (c, deuda) => {
  const tuyo = EST_PRECIO - deuda;
  const bien = tuyo > 0 ? (EST_PRECIO * (1 + c.sube) - Math.max(0, deuda - EST_AMORTIZA)) / tuyo : 0;
  const mal = tuyo > 0 ? Math.max(0, EST_PRECIO * (1 - c.baja) - deuda) / tuyo : 0;
  const okBien = bien >= EST_META_BIEN - 1e-9, okMal = mal >= EST_META_MAL - 1e-9;
  return { tuyo, bien, mal, okBien, okMal, nivel: okBien && okMal ? "exito" : okBien || okMal ? "parcial" : "fallo" };
};

function JuegoEstructura({ ayuda, onFin }) {
  const [caso] = useState(() => casoEstructura(ayuda));
  const [deuda, setDeuda] = useState(0);
  const [cerrado, setCerrado] = useState(null);
  const r = resultadoEstructura(caso, deuda);
  const x = (v) => v.toFixed(1).replace(".", ",") + "x";

  const cierre = {
    exito: "Punto justo. Con esa deuda tu dinero rinde de verdad si sale bien, y si sale mal te queda con qué volver a empezar.",
    parcial: r.okBien
      ? "Si sale bien ganas mucho, pero pediste tanto que un mal año se lleva casi todo lo que pusiste."
      : "Estás a salvo si sale mal, pero pusiste tanto de tu bolsillo que si sale bien tu dinero apenas rinde.",
    fallo: "No cumples ninguna de las dos metas: ni ganas lo suficiente si sale bien, ni aguantas si sale mal.",
  };

  return (
    <div className="ea-jw">
      <Pista>
        Compras <strong>{caso.nombre}</strong> por <strong>{EST_PRECIO} millones</strong>. Tú pones una parte y
        el banco te presta el resto. Pedir prestado hace que ganes más si sale bien… y que pierdas más si sale mal.
      </Pista>

      {/* la situación, siempre a la vista: la Pista de arriba se pliega */}
      <div className="ea-estCaso">
        Compras <strong>{caso.nombre}</strong> por <strong>{EST_PRECIO} millones</strong>. ¿Cuánto le pides al banco?
      </div>

      <div className="ea-est">
        <div className="ea-estL">
          <span>El banco te presta</span>
          <span className="ea-mono">{deuda} millones</span>
        </div>
        <input className="ea-slider" type="range" min="0" max={EST_TOPE} step="5" value={deuda} disabled={!!cerrado}
          onChange={(e) => setDeuda(entero(e.target.value, 0, 0, EST_TOPE))} aria-label="Cuánto te presta el banco" />
      </div>

      {/* quién pone qué */}
      <div className="ea-mix" style={{ marginTop: 6 }}>
        <div className="ea-mixSeg efe" style={{ width: r.tuyo + "%" }}>{r.tuyo >= 18 ? "tú " + r.tuyo : ""}</div>
        <div className="ea-mixSeg cart" style={{ width: deuda + "%" }}>{deuda >= 18 ? "banco " + deuda : ""}</div>
      </div>

      <div className="ea-escen">
        <div className={"ea-escenC " + (r.okBien ? "bien" : "mal")}>
          <div className="ea-lecK">Si le va bien · vale {Math.round(caso.sube * 100)}% más</div>
          <div className="ea-escenV ea-mono">{x(r.bien)}</div>
          <div className="ea-escenX">tu dinero se multiplica por {x(r.bien)}</div>
          <div className="ea-estMeta">{r.okBien ? "✓" : "✗"} Meta: {x(EST_META_BIEN)} o más</div>
        </div>
        <div className={"ea-escenC " + (r.okMal ? "bien" : "mal")}>
          <div className="ea-lecK">Si le va mal · vale {Math.round(caso.baja * 100)}% menos</div>
          <div className="ea-escenV ea-mono">{Math.round(r.mal * 100)}%</div>
          <div className="ea-escenX">{r.mal <= 0.005 ? "lo pierdes todo: el banco cobra primero" : "de tu dinero te queda el " + Math.round(r.mal * 100) + "%"}</div>
          <div className="ea-estMeta">{r.okMal ? "✓" : "✗"} Meta: conservar {Math.round(EST_META_MAL * 100)}% o más</div>
        </div>
      </div>

      {!cerrado ? (
        <button className="ea-btn" onClick={() => setCerrado(r.nivel)}>Cerrar el trato así</button>
      ) : (
        <div>
          <div className={"ea-alerta " + (cerrado === "exito" ? "bien" : cerrado === "fallo" ? "mal" : "")}>{cierre[cerrado]}</div>
          <button className="ea-btn" onClick={() => onFin(cerrado)}>Continuar</button>
        </div>
      )}
    </div>
  );
}

/* ---- Banderas rojas ----
   Reescrito. Los tres cambios que importan:
   · cada línea, la marques o no, explica al final por qué era o no era
     una bandera roja. Antes solo se pintaba de verde y el jugador se
     quedaba igual de ciego que al empezar.
   · el resultado distingue tres cosas distintas: las que cazaste, las
     que se te pasaron y las que marcaste de más. No es lo mismo fallar
     por no ver un problema que por ver problemas donde no los hay.
   · en modo aprendiz se dice antes de empezar qué tipo de cosa buscar,
     porque a quien nunca ha leído unos estados financieros no se le
     puede pedir que adivine el criterio. */
function JuegoBanderas({ ayuda, onFin, modo }) {
  const CUANTAS = 3;
  const [caso] = useState(() => {
    const b = elegirAzar(BANDERAS) || BANDERAS[0];
    /* con criterio alto se descartan señuelos, y se dice cuántos */
    const quitar = ayuda >= 65 ? 2 : ayuda >= 45 ? 1 : 0;
    const malas = (b.mal || []).map((x, i) => ({ ...x, id: "m" + i, roja: true }));
    const buenas = (b.ok || []).map((x, i) => ({ ...x, id: "b" + i, roja: false }))
      .sort(() => Math.random() - 0.5).slice(0, Math.max(2, 5 - quitar));
    return {
      t: b.t, doc: b.doc, pista: b.pista, quitar,
      lista: malas.concat(buenas).sort(() => Math.random() - 0.5),
    };
  });
  const [sel, setSel] = useState([]);
  const [rev, setRev] = useState(false);

  const marcada = (it) => sel.indexOf(it.id) >= 0;
  const marcar = (it) => {
    if (rev) return;
    if (marcada(it)) setSel(sel.filter((y) => y !== it.id));
    else if (sel.length < CUANTAS) setSel(sel.concat(it.id));
  };

  const rojas = caso.lista.filter((x) => x.roja);
  const cazadas = rojas.filter(marcada);
  const perdidas = rojas.filter((x) => !marcada(x));
  const falsas = caso.lista.filter((x) => !x.roja && marcada(x));
  const aciertos = cazadas.length;

  const veredicto = aciertos === CUANTAS
    ? "Las tres. Levantaste exactamente lo que había que levantar y no te inventaste problemas donde no los había."
    : aciertos === CUANTAS - 1
      ? "Dos de tres. Suficiente para que el asunto escale, y la que se te pasó es de las que salen caras."
      : aciertos === 1
        ? "Solo una. Con este informe la operación sigue adelante creyendo que está limpia."
        : "Ninguna. Marcaste ruido operativo y dejaste pasar los tres problemas de verdad.";

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>Marcadas {sel.length} de {CUANTAS}</span>
        <span>{caso.quitar > 0 ? "Tu criterio descartó " + caso.quitar + (caso.quitar === 1 ? " señuelo" : " señuelos") : "Sin descartes"}</span>
      </div>

      {caso.doc && (
        <div className="ea-docK ea-dis">Sobre la mesa · {caso.doc}</div>
      )}
      <p className="ea-qtxt" style={{ marginTop: 8 }}>{caso.t}</p>

      {modo === "aprendiz" && caso.pista && !rev && (
        <div className="ea-glos">
          <div className="ea-glosK">Qué estás buscando</div>
          <div className="ea-glosX">{caso.pista}</div>
        </div>
      )}

      <div className="ea-ops" style={{ marginTop: 12 }}>
        {caso.lista.map((it) => {
          let cls = "ea-check";
          if (rev) cls += it.roja ? " bien" : marcada(it) ? " mal" : "";
          else if (marcada(it)) cls += " sel";
          return (
            <button className={cls} key={it.id} disabled={rev} onClick={() => marcar(it)}>
              <span className="ea-checkB ea-mono">{marcada(it) ? "X" : "·"}</span>
              <span>
                {it.t}
                {rev && (
                  <span className="ea-checkX">
                    <span className={"ea-checkR ea-dis" + (it.roja ? " roja" : "")}>
                      {it.roja
                        ? (marcada(it) ? "Bandera roja · la viste" : "Bandera roja · se te pasó")
                        : (marcada(it) ? "No lo era · la marcaste de más" : "No lo era")}
                    </span>
                    {it.x}
                  </span>
                )}
              </span>
            </button>
          );
        })}
      </div>

      {!rev ? (
        <button className="ea-btn" disabled={sel.length < CUANTAS} onClick={() => setRev(true)}>Entregar el informe</button>
      ) : (
        <div>
          <div className={"ea-alerta " + (aciertos === CUANTAS ? "bien" : aciertos === CUANTAS - 1 ? "" : "mal")}>
            {veredicto}
          </div>
          <div className="ea-tabla" style={{ marginTop: 10 }}>
            <span className="ea-td">Banderas que cazaste</span><span className="ea-tdn ea-mono">{cazadas.length} de {CUANTAS}</span>
            <span className="ea-td">Se te pasaron</span><span className="ea-tdn ea-mono">{perdidas.length}</span>
            <span className="ea-td">Marcaste de más</span><span className="ea-tdn ea-mono">{falsas.length}</span>
          </div>
          {falsas.length > 0 && (
            <div className="ea-expl">
              Marcar de más también cuesta: en una operación real, levantar tres alarmas falsas quema tu
              credibilidad para el día que la alarma sea verdadera.
            </div>
          )}
          <button className="ea-btn" onClick={() => onFin(aciertos === CUANTAS ? "exito" : aciertos === CUANTAS - 1 ? "parcial" : "fallo")}>Continuar</button>
        </div>
      )}
    </div>
  );
}

/* ---- La pizarra del comité: pares de concepto y significado ---- */
/* Cada par lleva su color, el mismo en el concepto y en su definición:
   al destapar una ficha el color se queda en la memoria mucho mejor que
   un texto de dos palabras, y sirve de ancla para saber dónde estaba su
   pareja. Sin el rojo, que en todo el juego significa fallo, y sin el
   turquesa, que al lado del azul se confunde a simple vista. */
const COLORES_PARES = [0, 1, 3, 4, 5, 7].map((i) => COLORES_MEM[i].c);

/* Segundos con la pizarra destapada antes de empezar. Más con mejor
   atributo, para que «te ayuda» siga significando algo aquí. */
const vistaParesDe = (ayuda) => clamp(Math.round(5 + numero(ayuda, 0) / 25), 5, 9);

function JuegoPares({ ayuda, onFin }) {
  const [pz] = useState(() => elegirAzar(PIZARRAS));
  const [fichas] = useState(() => {
    /* los colores también se barajan: que el WACC no sea siempre cobre */
    const cols = COLORES_PARES.slice().sort(() => Math.random() - 0.5);
    const arr = [];
    pz.p.forEach((par, i) => {
      const col = cols[i % cols.length];
      arr.push({ id: i + "a", par: i, t: par[0], col });
      arr.push({ id: i + "b", par: i, t: par[1], col });
    });
    return arr.sort(() => Math.random() - 0.5);
  });
  const maxErr = clamp(4 + Math.floor(ayuda / 22), 4, 8);
  const [abiertas, setAbiertas] = useState([]);
  const [hechas, setHechas] = useState([]);
  const [err, setErr] = useState(0);
  const [fin, setFin] = useState(false);
  const [cuenta, setCuenta] = useState(() => vistaParesDe(ayuda));
  const mirando = cuenta > 0;
  const bloqueo = useRef(false);

  /* la pizarra destapada, y la cuenta atrás hasta taparla */
  useEffect(() => {
    if (cuenta <= 0) return;
    const t = setTimeout(() => setCuenta((c) => c - 1), 1000);
    return () => clearTimeout(t);
  }, [cuenta]);

  const cerrar = (nivel) => { setFin(true); setTimeout(() => onFin(nivel), 900); };

  const tocar = (f) => {
    if (mirando || fin || bloqueo.current) return;
    if (hechas.indexOf(f.par) >= 0) return;
    if (abiertas.some((x) => x.id === f.id)) return;
    const nuevas = abiertas.concat(f);
    setAbiertas(nuevas);
    if (nuevas.length < 2) return;
    bloqueo.current = true;
    if (nuevas[0].par === nuevas[1].par) {
      setTimeout(() => {
        const h = hechas.concat(nuevas[0].par);
        setHechas(h); setAbiertas([]); bloqueo.current = false;
        if (h.length === pz.p.length) cerrar(err === 0 ? "exito" : err <= 2 ? "exito" : "parcial");
      }, 420);
    } else {
      setTimeout(() => {
        const e = err + 1;
        setErr(e); setAbiertas([]); bloqueo.current = false;
        if (e >= maxErr) cerrar(hechas.length >= pz.p.length - 2 ? "parcial" : "fallo");
      }, 750);
    }
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>{mirando ? "Mira la pizarra" : pz.t}</span>
        <span>{mirando
          ? "se tapa en " + cuenta + (cuenta === 1 ? " segundo" : " segundos")
          : "Fallos " + err + " de " + maxErr}</span>
      </div>
      <div className="ea-tab4">
        {fichas.map((f) => {
          const hecha = hechas.indexOf(f.par) >= 0;
          const abierta = abiertas.some((x) => x.id === f.id);
          const vista = mirando || hecha || abierta;
          return (
            <div key={f.id} {...pulsable(() => tocar(f), vista ? f.t : "Ficha tapada", hecha || mirando)}
              className={"ea-fichaP" + (mirando ? " vista" : hecha ? " hecha" : abierta ? " abierta" : " tapada")
                + (vista ? " pintada" : "")}
              style={vista ? { background: f.col + "33", borderColor: f.col } : undefined}>
              {vista ? f.t : ""}
            </div>
          );
        })}
      </div>
      {mirando && (
        <button className="ea-mini" style={{ marginTop: 10 }} onClick={() => setCuenta(0)}>
          Ya lo miré, empezar
        </button>
      )}
      <div style={{ minHeight: 20, marginTop: 9, fontSize: 13, color: "#6B6B6B" }}>
        {fin ? (hechas.length === pz.p.length ? "Pizarra completa" : "Se acabaron los intentos")
          : mirando ? "Cada par tiene su color: el concepto y su definición se pintan igual." : ""}
      </div>
    </div>
  );
}

/* ---- El carril del capital ---- */
function JuegoCarril({ ayuda, onFin }) {
  const TOTAL = 26;
  const [carril, setCarril] = useState(1);
  const [objs, setObjs] = useState([]);
  const [t, setT] = useState(0);
  const [pts, setPts] = useState(0);
  const [golpes, setGolpes] = useState(0);
  const [fin, setFin] = useState(false);
  const carrilRef = useRef(1);
  useEffect(() => { carrilRef.current = carril; }, [carril]);

  const vel = 22;
  const probMalo = clamp(0.5 - ayuda / 320, 0.28, 0.5);

  useEffect(() => {
    if (fin) return;
    const id = setTimeout(() => {
      setObjs((prev) => {
        let lista = prev.map((o) => ({ ...o, y: o.y + vel }));
        if (t < TOTAL && t % 2 === 0) {
          const c = Math.floor(Math.random() * 3);
          lista = lista.concat({ k: t, c, y: -30, malo: Math.random() < probMalo, tocado: false });
        }
        lista.forEach((o) => {
          if (!o.tocado && o.y >= 170 && o.y <= 205 && o.c === carrilRef.current) {
            o.tocado = true;
            if (o.malo) setGolpes((g) => g + 1);
            else setPts((p) => p + 1);
          }
        });
        return lista.filter((o) => o.y < 240);
      });
      if (t >= TOTAL + 8) { setFin(true); return; }
      setT(t + 1);
    }, 190);
    return () => clearTimeout(id);
  }, [t, fin, probMalo]);

  const cerrar = () => {
    const neto = pts - golpes * 2;
    onFin(neto >= 6 ? "exito" : neto >= 2 ? "parcial" : "fallo");
  };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Retornos {pts}</span><span>Golpes {golpes}</span></div>
      <div className="ea-pistaC">
        <div className="ea-lineaC" style={{ left: "33.3%" }} />
        <div className="ea-lineaC" style={{ left: "66.6%" }} />
        {objs.map((o) => (
          <div key={o.k} className={"ea-obj " + (o.malo ? "malo" : "bueno")}
            style={{ left: o.c * 33.3 + 3.6 + "%", top: o.y + "px", opacity: o.tocado ? 0.25 : 1 }}>
            {o.malo ? CARRILES[o.c].malo : CARRILES[o.c].bueno}
          </div>
        ))}
        <div className="ea-cap" style={{ left: carril * 33.3 + 3.6 + "%" }}>Tu capital</div>
      </div>
      {/* Una barra en vez de tres botones: mover el capital con el dedo o
          con las flechas es mucho mas rapido que apuntar a un boton
          mientras las cosas siguen cayendo. */}
      <input className="ea-slider ea-carrilS" type="range" min="0" max="2" step="1" value={carril}
        disabled={fin} aria-label="Carril de tu capital"
        onChange={(e) => setCarril(entero(e.target.value, 1, 0, 2))} />
      <div className="ea-carrilN">
        {CARRILES.map((c, i) => (
          <span key={i} className={"ea-carrilE ea-dis" + (carril === i ? " on" : "")}>{c.n}</span>
        ))}
      </div>
      {fin && (
        <div>
          <div className={"ea-alerta " + (pts - golpes * 2 >= 6 ? "bien" : pts - golpes * 2 >= 2 ? "" : "mal")}>
            Cerraste con {pts} retornos y {golpes} golpes. Rotar entre activos captura oportunidades y también te expone
            justo cuando el carril equivocado se pone feo.
          </div>
          <button className="ea-btn" onClick={cerrar}>Continuar</button>
        </div>
      )}
    </div>
  );
}

/* ---- Cuatro en línea contra la contraparte ---- */
const COLS = 7, FILAS = 6;
function JuegoCuatro({ ayuda, onFin }) {
  const [tab, setTab] = useState(() => Array(COLS * FILAS).fill(null));
  const [bloqueo, setBloqueo] = useState(false);
  const [estado, setEstado] = useState(null);
  const [linea, setLinea] = useState([]);
  const torpeza = clamp(ayuda / 170, 0.05, 0.5);

  const idx = (c, f) => f * COLS + c;
  const alturaCol = (bd, c) => { let f = 0; while (f < FILAS && bd[idx(c, f)]) f++; return f; };
  const libres = (bd) => { const l = []; for (let c = 0; c < COLS; c++) if (alturaCol(bd, c) < FILAS) l.push(c); return l; };

  const ganadorEn = (bd, p) => {
    const dirs = [[1, 0], [0, 1], [1, 1], [1, -1]];
    for (let c = 0; c < COLS; c++) for (let f = 0; f < FILAS; f++) {
      for (const d of dirs) {
        const cel = [];
        for (let k = 0; k < 4; k++) {
          const cc = c + d[0] * k, ff = f + d[1] * k;
          if (cc < 0 || cc >= COLS || ff < 0 || ff >= FILAS) { cel.length = 0; break; }
          if (bd[idx(cc, ff)] !== p) { cel.length = 0; break; }
          cel.push(idx(cc, ff));
        }
        if (cel.length === 4) return cel;
      }
    }
    return null;
  };

  const soltar = (bd, c, p) => {
    const f = alturaCol(bd, c);
    if (f >= FILAS) return null;
    const n = bd.slice(); n[idx(c, f)] = p; return n;
  };

  const jugadaIA = (bd) => {
    const l = libres(bd);
    for (const c of l) { const n = soltar(bd, c, "O"); if (n && ganadorEn(n, "O")) return c; }
    for (const c of l) { const n = soltar(bd, c, "X"); if (n && ganadorEn(n, "X")) return c; }
    if (Math.random() < torpeza) return elegirAzar(l);
    const seguras = l.filter((c) => {
      const n = soltar(bd, c, "O");
      const m = soltar(n, c, "X");
      return !(m && ganadorEn(m, "X"));
    });
    const cand = seguras.length ? seguras : l;
    return cand.reduce((mej, c) => (Math.abs(c - 3) < Math.abs(mej - 3) ? c : mej), cand[0]);
  };

  const terminar = (n, l) => { setEstado(n); setLinea(l || []); setBloqueo(true); setTimeout(() => onFin(n), 1150); };

  const jugar = (c) => {
    if (bloqueo || estado) return;
    const n = soltar(tab, c, "X");
    if (!n) return;
    setTab(n);
    const g = ganadorEn(n, "X");
    if (g) { terminar("exito", g); return; }
    if (libres(n).length === 0) { terminar("parcial"); return; }
    setBloqueo(true);
    setTimeout(() => {
      const c2 = jugadaIA(n);
      const n2 = soltar(n, c2, "O");
      setTab(n2);
      const g2 = ganadorEn(n2, "O");
      if (g2) { terminar("fallo", g2); return; }
      if (libres(n2).length === 0) { terminar("parcial"); return; }
      setBloqueo(false);
    }, 430);
  };

  const txt = { exito: "Cierras en tus términos", parcial: "Tablero lleno, partieron la diferencia", fallo: "Te ganaron la posición" };

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Tus fichas en cobre</span><span>Lectura de la contraparte {Math.round(100 - torpeza * 100)}</span></div>
      <div className="ea-pista4">
        {Array.from({ length: COLS }, (_, c) => (
          <div className="ea-col4" key={c} {...pulsable(() => jugar(c), "Soltar ficha en la columna " + (c + 1))}>
            {Array.from({ length: FILAS }, (_, f) => {
              const v = tab[idx(c, f)];
              return <div key={f} className={"ea-hueco" + (v === "X" ? " mia" : v === "O" ? " suya" : "") + (linea.indexOf(idx(c, f)) >= 0 ? " gana" : "")} />;
            })}
          </div>
        ))}
      </div>
      <div style={{ minHeight: 22, marginTop: 11, fontSize: 14, color: "#6B6B6B" }}>{estado ? txt[estado] : "Toca una columna para soltar tu ficha."}</div>
    </div>
  );
}

/* ---- El comité de inversión ----
   Tres negocios sobre la mesa y capital para uno. No hay pistas: están
   los cinco datos y hay que decidir. Es el modo que entrena lo único
   que de verdad hace falta para gestionar un fondo, que es distinguir
   un buen negocio de uno que solo lo parece. */
function JuegoComite({ ayuda, onFin }) {
  const [mesa] = useState(() => {
    const pool = EMPRESAS.slice().sort(() => Math.random() - 0.5);
    /* con criterio alto la diferencia entre el mejor y el resto es más clara */
    const cuantos = 3;
    const elegidas = pool.slice(0, cuantos).map((e) => ({ ...e, q: calidadDeal(e) }));
    return elegidas.sort(() => Math.random() - 0.5);
  });
  const [sel, setSel] = useState(null);

  const orden = mesa.slice().sort((a, b) => b.q - a.q);
  const mejor = orden[0];
  const elegido = sel == null ? null : mesa[sel];
  const puesto = elegido ? orden.findIndex((x) => x.n === elegido.n) : -1;

  const nivel = puesto === 0 ? "exito" : puesto === 1 ? "parcial" : "fallo";
  const cierre = puesto === 0
    ? "Elegiste el mejor de los tres. Fíjate en qué te lo dijo: no era el que más crecía, era el que crecía con margen, sin depender de un cliente y sin deuda encima."
    : puesto === 1
      ? "Segundo mejor. Defendible en un comité, y aun así había uno claramente superior."
      : "Te quedaste con el peor de los tres. Casi siempre pasa por mirar el crecimiento y no mirar de quién depende la facturación.";

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis">
        <span>Tres negocios · capital para uno</span>
        <span>{ayuda >= 60 ? "Tu criterio ya descarta lo obvio" : "Sin pistas"}</span>
      </div>
      <Pista>
        Estos son los cinco datos con los que se decide de verdad. Crecer y tener margen suman;
        depender de un solo cliente y arrastrar deuda restan casi lo mismo. Elige uno.
      </Pista>

      {mesa.map((e, i) => {
        const marcado = sel === i;
        const esMejor = sel != null && e.n === mejor.n;
        return (
          <div key={e.n} className={"ea-deal" + (marcado ? " sel" : "") + (sel != null && esMejor ? " gana" : "")}>
            <div className="ea-itemTop">
              <span className="ea-itemN">{e.n}</span>
              <span className="ea-mono" style={{ fontSize: 12, flexShrink: 0 }}>{e.s}</span>
            </div>
            <div className="ea-dealS">
              {senalesDeal(e).map((x) => (
                <span key={x.k} className={"ea-sen" + (x.bien ? " bien" : x.mal ? " mal" : "")}>
                  <span className="ea-senK">{x.k}</span>
                  <span className="ea-senV ea-mono">{x.v}</span>
                </span>
              ))}
            </div>
            <div className="ea-itemD">{e.d}</div>
            {sel == null
              ? <button className="ea-mini" onClick={() => setSel(i)}>Poner el capital aquí</button>
              : <div className="ea-dealR">
                  {esMejor ? "Era el mejor de los tres" : "Múltiplo esperado " + baseDeal(e).toFixed(2) + "x"}
                  {marcado && !esMejor ? " · lo elegiste" : ""}
                </div>}
          </div>
        );
      })}

      {sel != null && (
        <div>
          <div className={"ea-alerta " + (nivel === "exito" ? "bien" : nivel === "fallo" ? "mal" : "")}>{cierre}</div>
          <button className="ea-btn" onClick={() => onFin(nivel)}>Continuar</button>
        </div>
      )}
    </div>
  );
}

/* ---- La subasta y la maldición del ganador ----
   Rehecha (28-sep-2026). La anterior tenía un tope escondido de ocho
   rondas: a la octava subida se acababa sola y lo contaba como si te
   hubieras retirado. Empezando en 40 y subiendo 8-13 por ronda, eso te
   echaba hacia los 110 aunque tu estimación fuera 145. Además el éxito
   pedía pagar menos del 82% del valor, que casi nunca pasaba, y los
   rivales se retiraban por sorteo en vez de por un límite propio.

   Ahora es una subasta de verdad, sin tope de rondas:
     · cada rival tiene su precio máximo (del 70% al 120% del valor) y se
       retira en cuanto la oferta lo pasa. Termina sola, porque los
       límites son finitos.
     · si te retiras, la subasta sigue sin ti: gana el rival con el límite
       más alto y paga lo que marca el segundo. Tu retirada se juzga por lo
       que pagó él: si pagó de más, hiciste bien.
   Medido con 30.000 subastas (atributo 72): pujar hasta tu estimación da
   éxito ~54% y fallo ~17%; retirarse muy pronto o pujar de más, bastante
   peor. Es la maldición del ganador sin necesidad de explicarla. */
const SUB_RIVALES = ["Fondo regional", "Comprador estratégico", "Family office"];
const pasoSubasta = (valor) => Math.max(4, Math.round(valor * 0.06)) + indiceAzar(4);
const casoSubasta = (ayuda) => {
  const valor = 60 + numero(Math.random(), 0.5) * 80;
  const ruido = Math.max(3, 20 - numero(ayuda, 0) / 6);
  return {
    valor,
    estimacion: Math.max(10, Math.round(valor + ruido * gauss())),
    limites: SUB_RIVALES.map(() => valor * (0.7 + numero(Math.random(), 0.5) * 0.5)),
    inicio: Math.round(valor * 0.5),
  };
};
/* si te retiras en p: gana el de límite más alto, al precio del segundo */
const cierreRetiro = (caso, p) => {
  const vivos = caso.limites.map((m, i) => ({ m, i })).filter((x) => x.m >= p).sort((x, y) => y.m - x.m);
  if (!vivos.length) return { quien: null, final: p };
  const final = Math.round(Math.max(p, vivos.length > 1 ? vivos[1].m : p));
  return { quien: SUB_RIVALES[vivos[0].i], final };
};
const nivelSubasta = (caso, fin) => {
  if (fin.gano) { const r = fin.precio / caso.valor; return r <= 1 ? "exito" : r <= 1.1 ? "parcial" : "fallo"; }
  if (fin.final > caso.valor) return "exito";
  return fin.precio >= caso.valor * 0.9 ? "parcial" : "fallo";
};

function JuegoSubasta({ ayuda, onFin }) {
  const [caso] = useState(() => casoSubasta(ayuda));
  const [precio, setPrecio] = useState(caso.inicio);
  const [siguiente, setSiguiente] = useState(() => caso.inicio + pasoSubasta(caso.valor));
  const [fuera, setFuera] = useState([null, null, null]);   /* precio al que se retiró cada rival */
  const [ronda, setRonda] = useState(1);
  const [fin, setFin] = useState(null);

  const subir = () => {
    if (fin) return;
    const nuevo = siguiente;
    const f = fuera.map((x, i) => (x == null && caso.limites[i] < nuevo ? nuevo : x));
    setPrecio(nuevo); setFuera(f); setRonda(ronda + 1);
    setSiguiente(nuevo + pasoSubasta(caso.valor));
    if (f.every((x) => x != null)) setFin({ gano: true, precio: nuevo });
  };
  const retirarse = () => {
    if (fin) return;
    const c = cierreRetiro(caso, precio);
    setFin({ gano: false, precio, final: c.final, quien: c.quien });
  };

  const nivel = fin ? nivelSubasta(caso, fin) : null;
  const V = Math.round(caso.valor);
  const texto = !fin ? null
    : fin.gano
      ? nivel === "exito" ? "Te la llevaste por " + fin.precio + " y valía " + V + ". Pagaste lo que vale o menos: ese es el trabajo."
        : nivel === "parcial" ? "Te la llevaste por " + fin.precio + " y valía " + V + ". Casi lo que vale: sin margen, pero sin daño."
        : "Te la llevaste por " + fin.precio + " y valía " + V + ". Ganaste la subasta y perdiste plata: eso es la maldición del ganador."
      : nivel === "exito" ? "Te retiraste en " + fin.precio + ". " + (fin.quien || "Un rival") + " se la llevó por " + fin.final + " y valía " + V + ": pagó de más. Retirarse a tiempo también es ganar."
        : nivel === "parcial" ? "Te retiraste en " + fin.precio + ". " + (fin.quien || "Un rival") + " se la llevó por " + fin.final + " y valía " + V + ". Se llevó una buena compra, pero te retiraste cerca del valor."
        : "Te retiraste en " + fin.precio + ". " + (fin.quien || "Un rival") + " se la llevó por " + fin.final + " y valía " + V + ". Dejaste ir una empresa barata: la prudencia también cuesta cuando sobra.";

  return (
    <div className="ea-jw">
      <div className="ea-jinfo ea-dis"><span>Tu estimación: {caso.estimacion} millones</span><span>Ronda {ronda}</span></div>
      <div className="ea-precio ea-mono">{precio}</div>
      <div style={{ fontSize: 12.5, color: "var(--gris)", marginBottom: 10 }}>
        Oferta sobre la mesa, en millones. Tu estimación puede fallar por arriba o por abajo.
      </div>
      {SUB_RIVALES.map((r, i) => (
        <div className={"ea-postor" + (fuera[i] == null ? "" : " fuera")} key={i}>
          <span>{r}</span><span className="ea-mono">{fuera[i] == null ? "sigue" : "se retiró en " + fuera[i]}</span>
        </div>
      ))}
      {!fin ? (
        <div className="ea-fila2">
          <button className="ea-btn" style={{ marginTop: 0, flex: 1 }} onClick={subir}>Subir a {siguiente}</button>
          <button className="ea-btn" style={{ marginTop: 0, flex: 1, background: "var(--rojo)" }} onClick={retirarse}>Retirarme</button>
        </div>
      ) : (
        <div>
          <div className={"ea-alerta " + (nivel === "exito" ? "bien" : nivel === "fallo" ? "mal" : "")}>{texto}</div>
          <button className="ea-btn" onClick={() => onFin(nivel)}>Continuar</button>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   TU CAMINO
   La pantalla final contaba cuánto dinero hiciste y no por dónde fuiste.
   Aquí se dibujan los tres árboles de la partida: en color lo que
   elegiste y lo que te trajo, en gris lo que dejaste pasar y cuántas
   escenas había detrás. Es la razón para vivir otra vida.
   ============================================================ */

/* ============================================================
   LOS FINALES
   El veredicto de arriba habla de dinero. Este habla de quién fuiste:
   sale de tus huellas, en orden de peso (una sanción pesa más que
   haberte quedado por lealtad), y se cuentan los que llevas vistos en
   todas tus vidas, como las consecuencias.
   ============================================================ */
const hu = (st, x) => !!(st && Array.isArray(st.huellas) && st.huellas.indexOf(x) >= 0);
const FINALES = [
  { id: "cazador", c: (st) => hu(st, "sancionado") && hu(st, "converso"), t: "Cazas lo que fuiste",
    x: "Te sancionaron por usar información privilegiada y terminaste en compliance, detectando a los que hacen lo mismo. Nadie los ve venir como tú." },
  { id: "sancionado", c: (st) => hu(st, "sancionado"), t: "Tu nombre sale primero",
    x: "Una sanción pública marcó todo lo que vino después. Se puede vivir con ella; lo que no se puede es borrarla." },
  { id: "impune", c: (st) => hu(st, "reincidente"), t: "Nunca te pillaron",
    x: "Usaste información privilegiada dos veces y nadie lo supo. Tu patrimonio lo sabe. Tú también." },
  { id: "complice", c: (st) => hu(st, "complice"), t: "Firmaste lo que no debías",
    x: "Un trimestre maquillado te persiguió el resto de la carrera. Una firma dura más que el año que arregla." },
  { id: "heroe", c: (st) => hu(st, "heroe"), t: "Levantaste la mano",
    x: "Denunciaste un ajuste contable y la investigación te dio la razón. En la firma, tu nombre quiere decir limpio." },
  { id: "unicornio", c: (st) => hu(st, "ticket_unicornio"), t: "Una de cada cien",
    x: "Pusiste un ticket pequeño en el negocio de un amigo y salió de esas que salen una de cada cien. Casi nunca pasa; a ti te pasó." },
  { id: "fundador", c: (st) => hu(st, "fundador"), t: "Fundaste algo que alguien compró",
    x: "Entraste a medio tiempo en la startup de tu amiga y salió vendida. Muchas historias de éxito empiezan con un sí a medias." },
  { id: "propia", c: (st) => !!(st && st.propia), t: "Tu nombre en la puerta",
    x: (st) => "Montaste " + FIRMA_DE(st).n.toLowerCase() + " y lo hiciste tuyo. Nadie más firma tus decisiones." },
  { id: "estafado", c: (st) => hu(st, "estafado"), t: "Familia es familia",
    x: "Le prestaste a tu primo sin papeles y desapareció con el dinero. Aprendiste lo que vale un contrato justo con la gente que más quieres." },
  { id: "primo", c: (st) => hu(st, "primo_exito"), t: "Creíste en tu primo",
    x: "Le prestaste cuando nadie más lo hacía y le fue de maravilla. Hay apuestas que se hacen por cariño y salen por talento." },
  { id: "dos_bandas", c: (st) => hu(st, "dos_bandas") || hu(st, "descubierto"), t: "Jugaste a dos bandas",
    x: "Cuando dos socias se pelearon la firma, tú les dijiste que sí a las dos. Esas cosas siempre se saben." },
  { id: "volviste", c: (st) => hu(st, "saltaste") && hu(st, "volviste"), t: "Te fuiste para volver mejor",
    x: "Te fuiste con un headhunter y volviste a tu antigua firma con más cargo. A veces irse es la mejor forma de que te valoren." },
  { id: "leal_delator", c: (st) => hu(st, "leal") && hu(st, "delator"), t: "Leal a la firma, no a las personas",
    x: "Rechazaste ofertas para quedarte y declaraste contra un colega. Tu lealtad fue siempre a la institución." },
  { id: "leal", c: (st) => hu(st, "leal") || hu(st, "leal_jefe"), t: "La lealtad como estrategia",
    x: "Te quedaste cuando podías irte y cargaste con culpas ajenas. La firma te lo pagó, a su manera y a su ritmo." },
  { id: "saltaste", c: (st) => hu(st, "saltaste"), t: "Siempre a la siguiente firma",
    x: "Cuando llamó el headhunter, dijiste que sí. Cada salto subió el sueldo y enfrió la red que dejabas atrás." },
  { id: "fuera", c: (st) => hu(st, "fuera"), t: "El 5% que dijiste que no",
    x: "Tu amiga montó su startup y tú elegiste quedarte fuera. Lo que pudo ser sigue ahí, en una nota de prensa." },
  { id: "ambicion", c: (st) => hu(st, "ambicion"), t: "La silla de arriba, a cualquier precio",
    x: "Fuiste por todas: cada mandato, cada fin de semana. La carrera se movió rápido y el resto esperó." },
  { id: "ritmo", c: (st) => hu(st, "ritmo"), t: "Subiste a tu ritmo",
    x: "Elegiste trabajar bien e irte a tu hora. Llegaste más tarde que otros y con la vida entera." },
  { id: "casi_propia", c: (st) => tipoRama(st) === "boutique", t: "Lo tuyo, casi",
    x: "Elegiste el camino de montar lo tuyo y nunca firmaste la renuncia. Te quedó el oficio, el sueldo fijo y la pregunta." },
  { id: "limpio", c: (st) => hu(st, "limpio") || hu(st, "te_negaste"), t: "Nunca tocaste lo que no era tuyo",
    x: "Te ofrecieron atajos, rumores y firmas fáciles, y no tomaste ninguno. No sale en el estado de cuenta, y se nota." },
  { id: "camino", c: () => true, t: "Un camino propio",
    x: "Ninguna gran apuesta te definió: fuiste sumando decisiones pequeñas, y todas eran tuyas." },
];
/* los de los lotes entran antes de los finales de carrera genéricos */
(() => {
  const nuevos = LOTES.finales.map((f) => ({ id: f.id, t: f.t, x: f.x,
    c: (st) => Array.isArray(f.huellas) && f.huellas.length > 0 && f.huellas.every((h) => hu(st, h)) }));
  const k = FINALES.findIndex((f) => f.id === "ambicion");
  FINALES.splice(k >= 0 ? k : FINALES.length - 1, 0, ...nuevos);
})();
const finalDe = (st) => FINALES.find((f) => { try { return f.c(st); } catch (e) { return false; } }) || FINALES[FINALES.length - 1];

const CLAVE_FINALES = "el-analista-finales";
const leerFinales = () => {
  try {
    if (typeof window === "undefined" || !window.localStorage) return [];
    const v = JSON.parse(window.localStorage.getItem(CLAVE_FINALES) || "[]");
    return Array.isArray(v) ? v.filter((id) => FINALES.some((f) => f.id === id)) : [];
  } catch (e) { return []; }
};
const anotarFinal = (id) => {
  try {
    if (typeof window === "undefined" || !window.localStorage) return;
    const v = leerFinales();
    if (v.indexOf(id) < 0) window.localStorage.setItem(CLAVE_FINALES, JSON.stringify(v.concat(id)));
  } catch (e) { /* sin almacen, se cuenta solo este */ }
};

function FinalHistoria({ s }) {
  const f = finalDe(s);
  useEffect(() => { anotarFinal(f.id); }, [f.id]);
  const vistos = unicos(leerFinales().concat(f.id));
  const texto = typeof f.x === "function" ? f.x(s) : f.x;
  return (
    <div className="ea-finalH">
      <div className="ea-finalHK ea-dis"><Icono k="corona" tam={16} />Tu final · {vistos.length} de {FINALES.length} descubiertos</div>
      <div className="ea-finalHT ea-dis">{f.t}</div>
      <p className="ea-finalHX">{texto}</p>
    </div>
  );
}

/* Lo que pudo pasar y lo que pasó. Cada tramo mide su probabilidad; la
   aguja cae en el que salió. Enseña sin decirlo que una buena decisión
   puede salir mal y una mala, bien. */
function BarraAzar({ azar }) {
  const ps = azar && Array.isArray(azar.ps) ? azar.ps : [];
  if (ps.length < 2) return null;
  const i = entero(azar.i, 0, 0, ps.length - 1);
  const antes = ps.slice(0, i).reduce((a, x) => a + x, 0);
  const centro = (antes + ps[i] / 2) * 100;
  const pct = (x) => Math.round(x * 100);
  return (
    <div className="ea-azar">
      <div className="ea-azarK ea-dis">Tenía un {pct(ps[i])}% de pasar</div>
      <div className="ea-azarB">
        {ps.map((x, k) => (
          <span key={k} className={"ea-azarT " + ((azar.tonos || [])[k] || "parcial") + (k === i ? " sale" : "")} style={{ width: (x * 100) + "%" }} />
        ))}
        <i className="ea-azarA" style={{ "--a": centro + "%" }} />
      </div>
      <div className="ea-azarL">
        {ps.map((x, k) => (
          <span key={k} className={k === i ? "sale" : ""}>{(azar.rots || [])[k] || ""} <b className="ea-mono">{pct(x)}%</b></span>
        ))}
      </div>
    </div>
  );
}

function CaminoFinal({ s }) {
  const camino = Array.isArray(s && s.camino) ? s.camino : [];
  const usados = [];
  let orden = 0;

  const nodo = (k, tono, hondo) => {
    usados.push(k);
    const paso = camino[k];
    const e = escenaDeId(paso.id, s);
    if (!e) return null;
    const ops = (Array.isArray(e.o) ? e.o : []).filter((o) => o && o.t);
    /* con caminos largos, el último nudo no puede tardar medio minuto */
    const retraso = Math.min(orden++, 24) * 90;
    /* lo que trajo la opción elegida: los pasos posteriores que cuelgan de ella */
    const hijosIds = luegosDe(ops[paso.o]);
    const hijos = [];
    camino.forEach((x, j) => {
      if (j > k && usados.indexOf(j) < 0 && hijosIds.indexOf(x.id) >= 0 && !hijos.some((h) => camino[h].id === x.id)) hijos.push(j);
    });
    hijos.forEach((j) => usados.push(j));
    return (
      <div className={"ea-nodo" + (hondo ? " ea-nodoHijo" : "")} key={k} style={{ borderColor: tono, animationDelay: retraso + "ms" }}>
        <div className="ea-nodoT ea-dis"><span className="ea-mono">{2026 + paso.a}</span>{e.t}</div>
        <div className="ea-rumbos">
          {ops.map((o, i) => {
            if (i !== paso.o) {
              const quedan = alcanceDe(o);
              return (
                <div className="ea-rumboNo" key={i}>
                  {o.t}
                  {quedan > 0 && <small>{quedan === 1 ? "1 escena que no viviste" : quedan + " escenas que no viviste"}</small>}
                </div>
              );
            }
            const azar = !!(o.chk || o.j || o.juego);
            const escena = o.azar && paso.r >= 0 && o.azar.esc && o.azar.esc[paso.r];
            return (
              <div className="ea-rumboSi" key={i} style={{ borderColor: tono, color: tono }}>
                <Icono k="check" tam={14} />
                <span>{o.t}</span>
                {escena ? <em>{escena.r}</em> : azar && <em>{paso.n === "fallo" ? "salió mal" : paso.n === "parcial" ? "a medias" : "salió bien"}</em>}
              </div>
            );
          })}
        </div>
        {/* Lo que trajo la opción elegida va debajo de TODAS las opciones
            del nudo: puesto justo bajo la elegida, la alternativa en gris
            quedaba al final de la sub-rama y parecía colgar de ella. */}
        {hijos.length > 0 && <div className="ea-hijos">{hijos.map((j) => nodo(j, tono, true))}</div>}
      </div>
    );
  };

  /* en el orden en que los viviste, y con el título de su raíz si no traen nombre */
  const [todos, setTodos] = useState(false);
  const arboles = ARBOLES.map((a) => ({ ...a, k: camino.findIndex((x) => a.raices.indexOf(x.id) >= 0) }))
    .filter((a) => a.k >= 0)
    .map((a) => ({ ...a, n: a.n || ((escenaDeId(camino[a.k].id, s) || {}).t) || "Una decisión" }))
    .sort((a, b) => a.k - b.k);
  const VISIBLES = 6;
  if (!arboles.length) return null;

  const descubiertas = unicos(leerArbol().concat(camino.map((x) => x.id).filter((id) => IDS_CONSEC.indexOf(id) >= 0)));
  const pct = Math.round(descubiertas.length / IDS_CONSEC.length * 100);
  return (
    <div className="ea-panel ea-camino">
      <div className="ea-rot ea-dis">Tu camino</div>
      <div className="ea-itemD">En color, lo que elegiste. En gris, lo que dejaste pasar.</div>
      {arboles.slice(0, todos ? arboles.length : VISIBLES).map((a) => (
        <div className="ea-arbol" key={a.n + a.k}>
          <div className="ea-arbolT ea-dis" style={{ color: a.c }}><Icono k="bifurca" tam={16} />{a.n}</div>
          {nodo(a.k, a.c, false)}
        </div>
      ))}
      {!todos && arboles.length > VISIBLES && (
        <button className="ea-btnO" style={{ marginTop: 18 }} onClick={() => setTodos(true)}>
          Ver los otros {arboles.length - VISIBLES} caminos
        </button>
      )}
      <div className="ea-descubre">
        <div className="ea-descubreN"><span className="ea-mono">{descubiertas.length}</span> de {IDS_CONSEC.length} consecuencias descubiertas en todas tus vidas</div>
        <div className="ea-descubreB"><div style={{ width: pct + "%" }} /></div>
      </div>
    </div>
  );
}

/* ---- piezas del informe de cierre ---- */

/* ============================================================
   EL INTERRUPTOR DEL MOVIMIENTO
   false = apagado · cualquier otra cosa = encendido.
   Vive fuera de React porque lo consultan componentes sueltos (la cifra
   que cuenta, el rodillo) que no tienen el estado de la partida a mano.
   El Motor lo pone al dia en cada render desde st.animar.
   ============================================================ */
let MOVIMIENTO = null;
/* Encendido por defecto. Seguir al sistema dejaba el juego quieto en
   cualquier Windows con los efectos de animacion apagados —un ajuste de
   rendimiento que casi nadie recuerda haber tocado—, y el rodillo del
   patrimonio y las cifras que cuentan son media gracia del juego. Quien
   se maree lo apaga en su Ficha y se queda apagado en todas sus vidas. */
const sinMovimiento = () => MOVIMIENTO === false;

/* ============================================================
   UNA CIFRA QUE CUENTA EN VEZ DE SALTAR
   El patrimonio es EL numero del juego y cambiaba de golpe: de 12.000 a
   19.400 sin que nada dijera que habias ganado. Verlo subir convierte un
   dato en una recompensa, que es de lo que vive un juego.

   Tres guardarraíles, porque esto corre tambien dentro del arnes de
   pruebas, que monta un window falso: sin requestAnimationFrame se pone
   el valor final y ya, y quien haya pedido menos movimiento en su
   sistema no ve ninguna animacion.
   ============================================================ */
function Cifra({ v, ms, desde: arranque }) {
  const fin = numero(v, 0);
  /* Donde no hay valor anterior que recordar —porque el componente se
     monta de cero, como en el cierre de anio— hay que decirle de donde
     viene, o se pinta ya en su destino y no cuenta nada. Justo lo que me
     paso: la cifra del cierre no animaba y parecia que si. */
  const inicial = esNumero(arranque) ? numero(arranque, 0) : fin;
  const [x, setX] = useState(inicial);
  const desde = useRef(inicial);
  useEffect(() => {
    const ini = numero(desde.current, 0);
    if (ini === fin) return;
    if (sinMovimiento() || typeof requestAnimationFrame !== "function" || typeof cancelAnimationFrame !== "function") {
      desde.current = fin; setX(fin); return;
    }
    const dura = numero(ms, 650);
    const t0 = Date.now();
    let id = 0, vivo = true;
    const paso = () => {
      if (!vivo) return;
      const p = clamp((Date.now() - t0) / dura, 0, 1);
      const e = 1 - Math.pow(1 - p, 3);   /* frena al llegar */
      setX(ini + (fin - ini) * e);
      if (p < 1) id = requestAnimationFrame(paso);
      else desde.current = fin;
    };
    id = requestAnimationFrame(paso);
    return () => { vivo = false; desde.current = fin; try { cancelAnimationFrame(id); } catch (e) {} };
  }, [fin]);
  return fmt(x);
}

/* ============================================================
   EL RODILLO
   La cifra del cierre contaba, pero contaba en una esquina y con letra
   de informe. El momento en que se sabe como fue el anio merece la
   pantalla entera: cada digito es un tambor que gira y se para, de
   izquierda a derecha, como el marcador de una maquina.

   Cada rueda lleva los diez digitos repetidos tres veces y aterriza en
   la tercera vuelta, asi que gira de verdad en vez de deslizarse al
   sitio. Los separadores de miles no giran: se quedan fijos, que es lo
   que hace que se lea el numero mientras se mueve.
   ============================================================ */
const RUEDA = [];
for (let v = 0; v < 3; v++) for (let d = 0; d <= 9; d++) RUEDA.push(d);

function Rodillo({ v }) {
  const txt = fmt(numero(v, 0));
  const [rodando, setRodando] = useState(true);
  const quieto = sinMovimiento();

  useEffect(() => {
    if (quieto) { setRodando(false); return; }
    setRodando(true);
    if (typeof setTimeout !== "function") { setRodando(false); return; }
    /* un respiro antes de soltar los frenos: sin esto el navegador pinta
       ya el estado final y no hay transicion que ver */
    const t = setTimeout(() => setRodando(false), 60);
    return () => { try { clearTimeout(t); } catch (e) {} };
  }, [txt, quieto]);

  if (quieto) return <span className="ea-rodillos ea-mono">{txt}</span>;

  const cifras = txt.split("");
  /* la rueda n tarda mas que la n-1, asi que el numero cuaja de
     izquierda a derecha y la ultima en pararse es la de las unidades */
  let idx = -1;
  return (
    <span className="ea-rodillos ea-mono" aria-label={"USD " + txt}>
      {cifras.map((c, i) => {
        if (!/[0-9]/.test(c)) return <span className="ea-rodSep" key={i}>{c}</span>;
        idx += 1;
        const destino = 20 + Number(c);   /* tercera vuelta */
        const dur = 900 + idx * 260;
        return (
          <span className="ea-rodillo" key={i} aria-hidden="true">
            <span className="ea-rodCol"
              style={{
                transform: "translateY(" + (rodando ? 0 : -destino * 100 / RUEDA.length) + "%)",
                transitionDuration: (rodando ? 0 : dur) + "ms",
                transitionTimingFunction: "cubic-bezier(.16,.84,.26,1)",
              }}>
              {RUEDA.map((d, k) => <span className="ea-rodD" key={k}>{d}</span>)}
            </span>
          </span>
        );
      })}
    </span>
  );
}

